globalThis.TX_SEASON = {"title": "棠西村秘闻", "sourceSha256": "b07470b34cc898a01d0cab70da7072c506d613fc1c0356cd7cc11b90c28b46c6", "start": "E00-S01", "chapters": [{"id": "E00", "title": "序章　七秒以后", "scenes": ["E00-S01", "E00-S02", "E00-S03", "E00-S04"]}, {"id": "E01", "title": "第一章　午夜便利店", "scenes": ["E01-S01", "E01-S02", "E01-S03", "E01-S04", "E01-S05"]}, {"id": "E02", "title": "第二章　卖不出去的阴宅", "scenes": ["E02-S01", "E02-S02", "E02-S03", "E02-S04", "E02-S05"]}, {"id": "E03", "title": "第三章　黑网吧·缺一人", "scenes": ["E03-S01", "E03-S02", "E03-S03", "E03-S04", "E03-S05"]}, {"id": "E04", "title": "第四章　肠粉摊的夜宵队", "scenes": ["E04-S01", "E04-S02", "E04-S03", "E04-S04"]}, {"id": "E05", "title": "第五章　楼顶晒衣绳", "scenes": ["E05-S01", "E05-S02", "E05-S03", "E05-S04", "E05-S05"]}, {"id": "E06", "title": "第六章　鱼缸房", "scenes": ["E06-S01", "E06-S02", "E06-S03", "E06-S04"]}, {"id": "E07", "title": "第七章　老生意街·三把钥匙", "scenes": ["E07-S01", "E07-S02", "E07-S03", "E07-S04", "E07-S05"]}, {"id": "E08", "title": "终章　今宵剧场", "scenes": ["E08-S01", "E08-S02", "E08-S03", "E08-S04", "E08-S05", "E08-S06", "E08-S07", "E08-S08"]}], "scenes": {
  "E00-S01": {"id": "E00-S01", "chapter": "E00", "title": "抄地址的人", "next": "E00-S02", "time": "3月19日 下午", "place": "剪辑桌", "cue": "耳机漏出半句求助；桌上两份外拍盒饭", "beats": [
    {"id": "E00-S01.b01", "sourceLine": 104, "type": "line", "speaker": "阿岑", "text": "你在米饭上写我名字干什么？"},
    {"id": "E00-S01.b02", "sourceLine": 106, "type": "line", "speaker": "林雨", "text": "上回你把我的鸡腿吃了。对，帮我看一下，昨晚这条怎么还在涨？"},
    {"id": "E00-S01.b03", "sourceLine": 108, "type": "line", "speaker": "手机·夜访", "text": "「三巷，姑娘喊人搭把手。整条巷，没人开门。」发布人：林雨。"},
    {"id": "E00-S01.b04", "sourceLine": 110, "type": "line", "speaker": "旁白", "text": "林雨拿筷子点开回复。一个叫“阿琴儿子”的账号发了张柜台上的照片。两个人侧身挤在货架前，阿琴只露出一只手。"},
    {"id": "E00-S01.b05", "sourceLine": 112, "type": "line", "speaker": "手机·阿琴儿子", "text": "我妈卖水的。你让他们买水就买水，别挡着收银。"},
    {"id": "E00-S01.b06", "sourceLine": 114, "type": "line", "speaker": "阿岑", "text": "你看见门没开了？"},
    {"id": "E00-S01.b07", "sourceLine": 116, "type": "line", "speaker": "林雨", "text": "我听完才发的。……等下。"},
    {"id": "E00-S01.b08", "sourceLine": 118, "type": "interaction", "kind": "inspect", "prompt": "滑动两条视频，查看字出现在哪一版。", "options": [{"id": "E00-S01.b08.o1", "label": "打开投稿原件", "sourceLine": 120, "feedback": [{"id": "E00-S01.b08.o1.f1", "type": "line", "sourceLine": 122, "speaker": "声画", "text": "女孩喊了一声“搭把手”，镜头切向卷闸，雨棚遮住了右边。第七秒，画面结束。没有字幕。"}]}, {"id": "E00-S01.b08.o2", "label": "打开《夜访》转发，再点“查看原片”", "sourceLine": 124, "feedback": [{"id": "E00-S01.b08.o2.f1", "type": "line", "sourceLine": 126, "speaker": "声画", "text": "相同的七秒连播两遍。第二遍，林雨打上去的那行字消失了；剩下雨声。"}]}]},
    {"id": "E00-S01.b09", "sourceLine": 128, "type": "line", "speaker": "林雨", "text": "这是我写的。给那个儿子回一下，告诉他我先把地址从评论里撤了。"},
    {"id": "E00-S01.b10", "sourceLine": 130, "type": "line", "speaker": "阿岑", "text": "你打，我把我的饭护好。"},
    {"id": "E00-S01.b11", "sourceLine": 132, "type": "line", "speaker": "手机·水果头像", "text": "投稿的是我。你从牌楼底下看看，镜头能拍到侧门吗？我这会儿得上班。"},
    {"id": "E00-S01.b12", "sourceLine": 134, "type": "line", "speaker": "旁白", "text": "林雨拨回去，没人接。她把原帖改为仅自己可见，发一条说明，置顶了儿子要求别堵门的留言，截掉其中的定位。"},
    {"id": "E00-S01.b13", "sourceLine": 136, "type": "line", "speaker": "林雨", "text": "本来想去棠西拍那块铁牌。今晚上我先去找老板。就去一趟，三脚架别搬。"}
  ]},
  "E00-S02": {"id": "E00-S02", "chapter": "E00", "title": "站回七秒里的位置", "next": "E00-S03", "time": "3月19日 傍晚", "place": "牌楼与雨棚", "cue": "公交刹车声渐远；受限横移；原片可随时回放", "beats": [
    {"id": "E00-S02.b01", "sourceLine": 143, "type": "line", "speaker": "林雨", "text": "各位晚上好，我是林雨。我们《夜访》群里那张旧厂铁牌，就在我后面。今天有件事得先说明白。"},
    {"id": "E00-S02.b02", "sourceLine": 145, "type": "line", "speaker": "阿岑", "text": "还开着吗？"},
    {"id": "E00-S02.b03", "sourceLine": 147, "type": "line", "speaker": "林雨", "text": "录我这段，回去发。直播先关。我怕又有人照着背景找过来。"},
    {"id": "E00-S02.b04", "sourceLine": 149, "type": "line", "speaker": "旁白", "text": "阿岑把直播界面滑到结束。林雨往牌楼右边让开一步，有个扎蓝布头巾的女人挟着一卷塑料绳走过去。她以为阿岑也在让。"},
    {"id": "E00-S02.b05", "sourceLine": 151, "type": "line", "speaker": "阿岑", "text": "往哪退？我后面是水沟。"},
    {"id": "E00-S02.b06", "sourceLine": 153, "type": "line", "speaker": "林雨", "text": "没事，你站住。"},
    {"id": "E00-S02.b07", "sourceLine": 155, "type": "interaction", "kind": "retry", "prompt": "对齐投稿的最后一帧。哪一处能同时重合？", "options": [{"id": "E00-S02.b07.o1", "label": "站到便利店正门，认整块灯牌", "sourceLine": 157, "feedback": [{"id": "E00-S02.b07.o1.f1", "type": "line", "sourceLine": 159, "speaker": "动作", "text": "整块灯牌都在头顶。原片里的“宵”字只露半边。往牌楼退两步，再看棚沿。"}], "retry": true}, {"id": "E00-S02.b07.o2", "label": "挪到缺角砖，让棚沿遮住半个“宵”", "sourceLine": 161, "feedback": [{"id": "E00-S02.b07.o2.f1", "type": "line", "sourceLine": 163, "speaker": "动作", "text": "卷闸在左，棚布垂下的黑边在右。林雨伸直胳膊，指尖后面一整片街面都让雨棚吃掉了。"}]}]},
    {"id": "E00-S02.b08", "sourceLine": 165, "type": "line", "speaker": "林雨", "text": "就这么窄。我要是往前走一步，那七秒就结束了。"},
    {"id": "E00-S02.b09", "sourceLine": 167, "type": "line", "speaker": "旁白", "text": "她掀开雨棚。扎头巾的女人已经不见了。门口有人拆一箱常温水，没空看她。"}
  ]},
  "E00-S03": {"id": "E00-S03", "chapter": "E00", "title": "只拍门", "next": "E00-S04", "time": "3月19日 入夜", "place": "今宵便利", "cue": "停机后街声恢复；柜盖有两段响", "beats": [
    {"id": "E00-S03.b01", "sourceLine": 174, "type": "line", "speaker": "阿琴", "text": "让一让。那箱你要买，就抬一头。不买也抬一头，挡着我了。"},
    {"id": "E00-S03.b02", "sourceLine": 176, "type": "line", "speaker": "旁白", "text": "林雨接过箱子，阿琴在她手下一垫，免得湿纸箱从底下散开。箱子落地，两个人手上都沾了纸屑。"},
    {"id": "E00-S03.b03", "sourceLine": 178, "type": "line", "speaker": "林雨", "text": "琴姐，是我在网上说没人开门。我来给您看原片。您愿意听我说两句吗？"},
    {"id": "E00-S03.b04", "sourceLine": 180, "type": "line", "speaker": "阿琴", "text": "你那个朋友，红灯亮着干吗？"},
    {"id": "E00-S03.b05", "sourceLine": 182, "type": "interaction", "kind": "choice", "prompt": "林雨怎样让阿琴看清来意？", "options": [{"id": "E00-S03.b05.o1", "label": "让她亲眼看阿岑停机", "sourceLine": 184, "feedback": [{"id": "E00-S03.b05.o1.f1", "type": "line", "sourceLine": 186, "speaker": "阿岑", "text": "这里。灭了。您要看刚才那段，我可以倒回去。"}, {"id": "E00-S03.b05.o1.f2", "type": "line", "sourceLine": 188, "speaker": "阿琴", "text": "行，你把机子搁水箱上。小心底下软。"}]}, {"id": "E00-S03.b05.o2", "label": "把解锁的手机交给她，阿岑盖镜头", "sourceLine": 190, "feedback": [{"id": "E00-S03.b05.o2.f1", "type": "line", "sourceLine": 192, "speaker": "阿琴", "text": "往回拉哪个？我这么一抹，它给我换歌了。"}, {"id": "E00-S03.b05.o2.f2", "type": "line", "sourceLine": 194, "speaker": "林雨", "text": "我扶下面。您按这个，原来就七秒。"}]}]},
    {"id": "E00-S03.b06", "sourceLine": 196, "type": "line", "speaker": "旁白", "text": "阿琴在卷闸放到底时，推开雨棚下的一扇窄门。刚才从牌楼看，连她的半边围裙都看不见。"},
    {"id": "E00-S03.b07", "sourceLine": 198, "type": "line", "speaker": "阿琴", "text": "昨天那阵雨，有人从这边进的。谁开的，你问当时值班的人。别又写我。"},
    {"id": "E00-S03.b08", "sourceLine": 200, "type": "line", "speaker": "林雨", "text": "好。我能拍一下这铰链？刚才站的位置我也补一张。"},
    {"id": "E00-S03.b09", "sourceLine": 202, "type": "line", "speaker": "阿琴", "text": "只拍门，手我自己的，拍就拍。拍完借你的手把这箱水推里头。"},
    {"id": "E00-S03.b10", "sourceLine": 204, "type": "line", "speaker": "林雨", "text": "您说买不买都抬，那我还是买瓶吧。"},
    {"id": "E00-S03.b11", "sourceLine": 206, "type": "line", "speaker": "阿琴", "text": "常温下面。上面那瓶我喝了一口。"},
    {"id": "E00-S03.b12", "sourceLine": 208, "type": "set", "text": "阿琴允许的门铰链影像", "record": "hinge", "scope": "public", "holder": "阿琴／夜访", "detail": "仅可示范当天的门、手与机位遮挡。"}
  ]},
  "E00-S04": {"id": "E00-S04", "chapter": "E00", "title": "今天先回去", "next": "E01-S01", "time": "3月19日 夜", "place": "公交站", "cue": "屏内消息；旧厂上传图和街口实景用不同边框", "beats": [
    {"id": "E00-S04.b01", "sourceLine": 215, "type": "line", "speaker": "旁白", "text": "阿岑放大棚边的定格。卷闸从头到尾一条缝都没动，窄门在画外响。林雨把两张图排在一起，亲口录下能确认的部分。"},
    {"id": "E00-S04.b02", "sourceLine": 217, "type": "interaction", "kind": "choice", "prompt": "给原来那条链接留下什么？", "options": [{"id": "E00-S04.b02.o1", "label": "恢复带遮挡的更正入口，置顶两帧对照；隐藏原定位", "sourceLine": 219, "feedback": [{"id": "E00-S04.b02.o1.f1", "type": "line", "sourceLine": 221, "speaker": "手机·夜访", "text": "原帖顶部显示更正卡，点开先见“这段拍不到侧门”。旧评论继续关闭。"}]}, {"id": "E00-S04.b02.o2", "label": "保持旧帖隐藏，以频道主页置顶更正", "sourceLine": 223, "feedback": [{"id": "E00-S04.b02.o2.f1", "type": "line", "sourceLine": 225, "speaker": "手机·夜访", "text": "旧帖显示不可见。主页的更正有日期和两帧对照。转发过的人收到更正链接。"}]}]},
    {"id": "E00-S04.b03", "sourceLine": 227, "type": "line", "speaker": "阿岑", "text": "你要把那女的也说进去？"},
    {"id": "E00-S04.b04", "sourceLine": 229, "type": "line", "speaker": "林雨", "text": "哪个？"},
    {"id": "E00-S04.b05", "sourceLine": 231, "type": "line", "speaker": "阿岑", "text": "你让路那个。我看你动了两次。声音我听见一点，像有人拿指甲拈塑料绳。"},
    {"id": "E00-S04.b06", "sourceLine": 233, "type": "line", "speaker": "林雨", "text": "头巾是蓝的。就这个我看得清。贴子里别写。"},
    {"id": "E00-S04.b07", "sourceLine": 235, "type": "line", "speaker": "手机·水果头像", "text": "明晚九点，三巷铁牌旁。我得亲眼看着你们关机。我中途有十分钟休息。"},
    {"id": "E00-S04.b08", "sourceLine": 237, "type": "line", "speaker": "林雨", "text": "那我也不隔着手机问你了。明晚见。"},
    {"id": "E00-S04.b09", "sourceLine": 239, "type": "line", "speaker": "旁白", "text": "两人挤上末班前的一趟车。阿岑翻出明天一早拍饮品的通告。林雨打个九点的闹钟，备注写“带原片，不开机”。玻璃上映着车里的每个人。站上那个蓝头巾的影子一直没跟过来。"}
  ]},
  "E01-S01": {"id": "E01-S01", "chapter": "E01", "title": "九点的约", "next": "E01-S02", "time": "3月20日 21:00", "place": "牌楼与雨棚", "cue": "铁牌离地一人高；夜班工牌反扣", "beats": [
    {"id": "E01-S01.b01", "sourceLine": 250, "type": "line", "speaker": "旁白", "text": "铁牌下的女人穿着薄外套，手上搭了两只外卖袋。林雨举起手，隔着几步把手机的录音、相机逐一关掉。"},
    {"id": "E01-S01.b02", "sourceLine": 252, "type": "line", "speaker": "小茵", "text": "对，别说我名字。我只有十分钟。这个手机你拿着，旧的，电用得很快。"},
    {"id": "E01-S01.b03", "sourceLine": 254, "when": "E00-S03.b05.o1", "type": "line", "speaker": "小茵", "text": "琴姐讲，你们昨天真的把机子给她看着关掉的。那我敢在这儿停一会儿。"},
    {"id": "E01-S01.b04", "sourceLine": 256, "when": "E00-S03.b05.o2", "type": "line", "speaker": "小茵", "text": "我看过你留给琴姐的那张图了。你手机先收起来，今天我们看我的。"},
    {"id": "E01-S01.b05", "sourceLine": 258, "type": "line", "speaker": "阿岑", "text": "我拿充电宝给你，我不碰手机。"},
    {"id": "E01-S01.b06", "sourceLine": 260, "type": "line", "speaker": "小茵", "text": "那天我替琴姐看铺。雨把铁牌旁的塑料绳扯松了，我在对街拍它给琴姐看，刚好有人喊。回传的只有前七秒；后头我把手机塞兜里，拍了一路黑布。我发给你是想问铁牌那三声。"},
    {"id": "E01-S01.permission.1", "type": "line", "speaker": "小茵", "text": "我看你在节目里说过，你能见着别人看不见的。我发给你听，你怎么没问过我，就让那么多人也听了？", "origin": "outline-bridge"},
    {"id": "E01-S01.permission.2", "type": "line", "speaker": "林雨", "text": "我看见投稿两个字，以为你要我发。是我没问。", "origin": "outline-bridge"},
    {"id": "E01-S01.b07", "sourceLine": 262, "type": "line", "speaker": "林雨", "text": "昨晚我们站到缺角砖上，最后一帧能对上。后来你往哪儿去了？"},
    {"id": "E01-S01.b08", "sourceLine": 264, "type": "line", "speaker": "小茵", "text": "横过街，推侧门，把人往里面叫。你不是来找没开门的人吗？你听见后面的脚步再看看我。"},
    {"id": "E01-S01.b09", "sourceLine": 266, "type": "line", "speaker": "阿岑", "text": "我们昨晚对齐的是截出去的最后一帧。你横过去的那段，真要只看屏幕，就是一片黑。"},
    {"id": "E01-S01.b10", "sourceLine": 268, "type": "line", "speaker": "小茵", "text": "还得回去接线。十点十八左右我来替琴姐对账。等我下了班，后面那段你们坐下听。"},
    {"id": "E01-S01.b11", "sourceLine": 270, "type": "line", "speaker": "旁白", "text": "她走到粉摊旁又折回来，拔走充电宝。阿岑看着空空的手。"},
    {"id": "E01-S01.b12", "sourceLine": 272, "type": "line", "speaker": "小茵", "text": "我拿着线才充得上啊。你这个人只借个头。"}
  ]},
  "E01-S02": {"id": "E01-S02", "chapter": "E01", "title": "走过沟以后还有一步", "next": "E01-S03", "time": "3月20日 22:18", "place": "便利店外", "cue": "固定柜盖与录音波形；檐下俯视玻璃反射", "beats": [
    {"id": "E01-S02.b01", "sourceLine": 279, "type": "line", "speaker": "旁白", "text": "阿琴掀起冰柜盖，把里面一包冻得发白的叉烧递给粉叔。盖子落回去，提手比盖沿晚响一下。小茵发来语音，隔着雨声，末尾的轻响一模一样。"},
    {"id": "E01-S02.b02", "sourceLine": 281, "type": "interaction", "kind": "inspect", "prompt": "回放小茵准许核对的尾音，找出第二声从哪来。", "options": [{"id": "E01-S02.b02.o1", "label": "点柜盖上的活动提手", "sourceLine": 283, "feedback": [{"id": "E01-S02.b02.o1.f1", "type": "line", "sourceLine": 285, "speaker": "动作", "text": "阿岑把盖压住，单弹提手。耳机里留下短而薄的一声。他写下“同类器物，在琴姐店内复响”，没有填写开门的人。"}]}, {"id": "E01-S02.b02.o2", "label": "点柜沿，再让阿琴把提手压住", "sourceLine": 287, "feedback": [{"id": "E01-S02.b02.o2.f1", "type": "line", "sourceLine": 289, "speaker": "动作", "text": "重响还在，轻响消失。阿岑把两次收音留为对照，小茵的语音始终只在耳机里回放。"}]}]},
    {"id": "E01-S02.b03", "sourceLine": 291, "type": "line", "speaker": "旁白", "text": "林雨往站牌走，想看看斜角的玻璃。她停步，耳麦里还有一步。一个穿夹克的男人在玻璃反光里停住。她朝左，他也跟着往左。"},
    {"id": "E01-S02.b04", "sourceLine": 293, "type": "line", "speaker": "林雨", "text": "阿岑，你先别转机器。你站到侧门边，我往你那儿走。"},
    {"id": "E01-S02.b05", "sourceLine": 295, "type": "line", "speaker": "阿岑", "text": "听到。我手空出来了。"},
    {"id": "E01-S02.b06", "sourceLine": 297, "type": "line", "speaker": "旁白", "text": "她背后紧跟的脚步慢了半拍。一把旧红伞已经撑在她身旁。伞下的女人把大半边让给她，露出一侧淋湿的肩膀。"}
  ]},
  "E01-S03": {"id": "E01-S03", "chapter": "E01", "title": "空碟", "next": "E01-S04", "time": "3月20日 深夜", "place": "今宵便利", "cue": "视觉只给林雨红伞人物；阿岑可听牌响，设备只收实体", "beats": [
    {"id": "E01-S03.b01", "sourceLine": 304, "type": "line", "speaker": "林雨", "text": "阿婆，我挨您一会儿，成吗？"},
    {"id": "E01-S03.b02", "sourceLine": 306, "type": "line", "speaker": "旁白", "text": "阿婆把伞柄贴到铁牌边。手腕上裹着蓝布，和昨晚扎头巾的布纹一模一样。三响。店里拖把杆倒在墙上，灯亮了。"},
    {"id": "E01-S03.b03", "sourceLine": 308, "type": "interaction", "kind": "choice", "prompt": "越过水沟，给店里的人一个信号。", "options": [{"id": "E01-S03.b03.o1", "label": "喊阿琴帮忙", "sourceLine": 310, "feedback": [{"id": "E01-S03.b03.o1.f1", "type": "line", "sourceLine": 312, "speaker": "林雨", "text": "琴姐，是我。您先别关门！"}, {"id": "E01-S03.b03.o1.f2", "type": "line", "sourceLine": 314, "speaker": "阿琴", "text": "我耳朵好得很。看脚下，扶门框。"}]}, {"id": "E01-S03.b03.o2", "label": "亮起手机照窄门的门槛", "sourceLine": 316, "feedback": [{"id": "E01-S03.b03.o2.f1", "type": "line", "sourceLine": 318, "speaker": "动作", "text": "阿岑伸脚踩住门。阿琴一眼认出林雨袖子上的纸屑，把拖把横在门边。"}]}]},
    {"id": "E01-S03.b04", "sourceLine": 320, "type": "line", "speaker": "阿琴", "text": "后面那位，要买什么？"},
    {"id": "E01-S03.b05", "sourceLine": 322, "type": "line", "speaker": "旁白", "text": "男人没答话。粉叔在两张桌子外头抽走挡路的小凳，托起一只空碟。"},
    {"id": "E01-S03.b06", "sourceLine": 324, "type": "line", "speaker": "粉叔", "text": "靓女，你那份还要不要？放到这会儿，凉了可别怪我。"},
    {"id": "E01-S03.threshold.1", "type": "line", "speaker": "旁白", "text": "小茵在窄门里侧看见她，把门往外多推了一掌宽。", "origin": "outline-bridge"},
    {"id": "E01-S03.b07", "sourceLine": 326, "type": "line", "speaker": "旁白", "text": "林雨刚想说自己没点，抬头看见粉叔的手稳稳端着空碟。她跨过水沟。阿岑靠门站，让开一步，等她进去才跟进来。两家店都有人往外看，男人掉头离开。"},
    {"id": "E01-S03.b08", "sourceLine": 328, "type": "line", "speaker": "林雨", "text": "这会儿能问一句了吧。我那份什么馅？"},
    {"id": "E01-S03.b09", "sourceLine": 330, "type": "line", "speaker": "粉叔", "text": "还挑？粉浆都没倒呢。"},
    {"id": "E01-S03.b10", "sourceLine": 332, "type": "line", "speaker": "旁白", "text": "他真开火。林雨拿了干毛巾追到檐下，伞尖刚才滴水的地方已经空了。"}
  ]},
  "E01-S04": {"id": "E01-S04", "chapter": "E01", "title": "张记糖水的桌子", "next": "E01-S05", "time": "3月21日 00:10", "place": "粉摊", "cue": "录音转入原件手机；店灯从近到远", "beats": [
    {"id": "E01-S04.b01", "sourceLine": 339, "type": "line", "speaker": "旁白", "text": "小茵端自己的碟子过来，把充电宝还给阿岑。大家听完原片：布擦过话筒，柜盖响，门轴响，有人进来躲雨。再过两秒，传出一个女人叫小茵乳名的声音。"},
    {"id": "E01-S04.b02", "sourceLine": 341, "type": "line", "speaker": "小茵", "text": "开门的是我。后面我妈喊我，哪条巷的人一听都认得。开门以后那截，留给我。"},
    {"id": "E01-S04.believe.1", "type": "line", "speaker": "小茵", "text": "你说相机拍不着那位阿婆，我信你。怎么轮到我说开了门，就得把手机拿出来？", "origin": "outline-bridge"},
    {"id": "E01-S04.believe.2", "type": "line", "speaker": "林雨", "text": "你跟我说就够了。要给别人交代那行字，是我欠的。", "origin": "outline-bridge"},
    {"id": "E01-S04.b03", "sourceLine": 343, "type": "line", "speaker": "阿岑", "text": "你在自己手机上截到这儿。你发哪段，我们留哪段。旧机你拿回去。"},
    {"id": "E01-S04.b04", "sourceLine": 345, "type": "line", "speaker": "林雨", "text": "昨天加那行字的是我。我给看过的人再说一遍。"},
    {"id": "E01-S04.b05", "sourceLine": 347, "when": "E00-S04.b02.o1", "type": "line", "speaker": "手机·评论通知", "text": "一位转发过旧链接的人点开更正，留言问“那姑娘后来进去了？”林雨只回能听清的那声开门。"},
    {"id": "E01-S04.b06", "sourceLine": 349, "when": "E00-S04.b02.o2", "type": "line", "speaker": "手机·私信", "text": "一个看过旧帖的人找不到链接，问她是不是心虚。林雨把置顶更正转给他，请阿岑帮忙检查去掉定位后的版本。"},
    {"id": "E01-S04.b07", "sourceLine": 351, "type": "line", "speaker": "旁白", "text": "她把经小茵听过的开门声补进更正，没去追那男人的背影。粉叔的方桌湿了，一张玻璃纸下面露出“张记糖水”四字。"},
    {"id": "E01-S04.b08", "sourceLine": 353, "type": "line", "speaker": "林雨", "text": "刚才的阿婆左肩膀湿了，我连毛巾都没赶上递。她以前坐这儿？"},
    {"id": "E01-S04.b09", "sourceLine": 355, "type": "line", "speaker": "粉叔", "text": "这桌是她家的，腿短的朝墙摆。人走了六年了。你盯我做什么？我没见她，我听见牌响。"},
    {"id": "E01-S04.b10", "sourceLine": 357, "type": "line", "speaker": "阿琴", "text": "她活着的时候，夜里有女孩一个人走，她拿伞送到车站。路上她也骂人，嫌人走得慢。"},
    {"id": "E01-S04.b11", "sourceLine": 359, "type": "line", "speaker": "旁白", "text": "林雨把毛巾搭在一张空椅子上。过一会有人来借，真拿去擦了头。"},
    {"id": "E01-S04.b12", "sourceLine": 361, "type": "set", "text": "开门声的限段许可", "record": "door-sound", "scope": "public", "holder": "小茵", "detail": "她亲自裁到门轴响。姓名、定位和母亲叫乳名的声音只留在本人手机。"}
  ]},
  "E01-S05": {"id": "E01-S05", "chapter": "E01", "title": "袋口朝上", "next": "E02-S01", "time": "3月21日 01:55 至3月27日", "place": "今宵便利与302", "cue": "机器多吐半截小票；租约以日历翻页", "beats": [
    {"id": "E01-S05.b01", "sourceLine": 368, "type": "line", "speaker": "旁白", "text": "一个老人站在蒸柜旁，伸手要四个叉烧包。阿岑看见牛皮纸袋从蒸柜滑下来，伸手一托，林雨却在跟半空里的人说话。"},
    {"id": "E01-S05.b02", "sourceLine": 370, "type": "line", "speaker": "老人", "text": "大的放上头。小的让他压扁了，回家他们又要换。"},
    {"id": "E01-S05.b03", "sourceLine": 372, "type": "line", "speaker": "旁白", "text": "纸袋坠到阿岑掌心，空的。阿琴打了个哈欠，给两人扫了一瓶水。收银机结完矿泉水的钱，额外吐出一截湿纸，上面只有“郑家楼”三个倒印的字。"},
    {"id": "E01-S05.b04", "sourceLine": 374, "type": "line", "speaker": "阿琴", "text": "福顺伯家。明早我带你们到楼口。你要想听他吃几个包，行。你要拿他的脸给人家看，我不会带你。"},
    {"id": "E01-S05.b05", "sourceLine": 376, "type": "line", "speaker": "旁白", "text": "3月21日清早，阿琴按约带两人走到楼口，郑家长子关着铺门。接下来六天，他们往返三次：等钥匙师傅收工，等楼主回电，给小茵看置顶更正。阿岑推掉一次早班跟拍，第二次已经得去挣工钱。"},
    {"id": "E01-S05.supper.1", "type": "line", "speaker": "旁白", "text": "其中一个晚上，小茵叫她来讲张婆婆撑伞时站在哪一边。隔天是林雨自己过来吃粉。两个人吃完一整碟，才发现今天谁也没带那部旧手机。", "origin": "outline-bridge"},
    {"id": "E01-S05.b06", "sourceLine": 378, "type": "line", "speaker": "阿岑", "text": "我一趟回去一趟过来，电池在车上充得比在家勤。你那个短租问了没有？咱们的外拍钱够付一间小的，别付两间。"},
    {"id": "E01-S05.b07", "sourceLine": 380, "type": "line", "speaker": "林雨", "text": "我也得有个地方剪婚宴片，电脑跟我颠着坏得快。先一个月。你来拍带电池，别拖行李，床宽九十。"},
    {"id": "E01-S05.b08", "sourceLine": 382, "type": "line", "speaker": "老许", "text": "三巷十二号，三楼临街。一个人住，每月九百，押一个月，水电看表。拍人先问，过道上别架机器。"},
    {"id": "E01-S05.b09", "sourceLine": 384, "type": "line", "speaker": "旁白", "text": "林雨用外拍账本支付首期，在租约上写到4月27日。老许带她看水表；阿岑替她搬了主机，把自己婚礼跟拍的闹钟改早半小时。"},
    {"id": "E01-S05.b10", "sourceLine": 386, "type": "line", "speaker": "林雨", "text": "许叔，能把床拽离墙一点吗？我想开底下那扇小柜门。"},
    {"id": "E01-S05.b11", "sourceLine": 388, "type": "line", "speaker": "老许", "text": "先摸摸床腿，我上一任租客垫了张旧票。抬，不要拖。"},
    {"id": "E01-S05.b12", "sourceLine": 390, "type": "line", "speaker": "旁白", "text": "床移开，柜里有一台旧电视，插头卷在柜脚。阿岑只看见自己映在玻璃上。林雨看见一张餐桌，有人等到包子的油浸透了纸袋。"},
    {"id": "E01-S05.b13", "sourceLine": 392, "type": "set", "text": "302短租与钥匙", "record": "lease", "scope": "private", "holder": "林雨／老许", "detail": "租约与房钥匙供居住和交还时核对。"}
  ]},
  "E02-S01": {"id": "E02-S01", "chapter": "E02", "title": "四个包", "next": "E02-S02", "time": "4月4日 下午", "place": "郑家楼前", "cue": "雨收了；铁门上贴着长子的售房电话", "beats": [
    {"id": "E02-S01.b01", "sourceLine": 403, "type": "line", "speaker": "旁白", "text": "林雨剥开阿琴新包的纸袋。四个叉烧包，有一个特意收得小，面皮上掐了一点花。"},
    {"id": "E02-S01.b02", "sourceLine": 405, "type": "line", "speaker": "阿琴", "text": "他家三仔一女。小的那个生得秀气，嘴可不小，谁吃不下都是她收尾。"},
    {"id": "E02-S01.b03", "sourceLine": 407, "type": "line", "speaker": "林雨", "text": "我见的人要四个。您为什么多捏这个花？"},
    {"id": "E02-S01.b04", "sourceLine": 409, "type": "line", "speaker": "阿琴", "text": "以前给阿梅认的。她送药那天下大雨，过马路没过成。你见了她爸，别拿这个开头。"},
    {"id": "E02-S01.b05", "sourceLine": 411, "type": "line", "speaker": "旁白", "text": "郑国强从隔壁门店过来，一把钥匙在掌心按出红印。他承认挂牌的是自己；父亲失踪后他逢人就问，越问房子越卖不动。阿岑问能不能看看当年张贴过的寻人启事。"},
    {"id": "E02-S01.b06", "sourceLine": 413, "type": "line", "speaker": "郑国强", "text": "看可以。楼梯也可以拍，我把灯开了。地下那间杂物房漏水，你们不许下去。"},
    {"id": "E02-S01.b07", "sourceLine": 415, "type": "line", "speaker": "阿岑", "text": "您还住在这儿？"},
    {"id": "E02-S01.b08", "sourceLine": 417, "type": "line", "speaker": "郑国强", "text": "我不住。你们先进，我十分钟要看铺。"},
    {"id": "E02-S01.b09", "sourceLine": 419, "type": "line", "speaker": "旁白", "text": "楼道里一下有了热包的香味。林雨转过身，阿琴提来的纸袋还系在阿岑腕上。"}
  ]},
  "E02-S02": {"id": "E02-S02", "chapter": "E02", "title": "一楼上面还是一楼", "next": "E02-S03", "time": "4月4日 黄昏", "place": "郑家楼梯与饭厅", "cue": "现实墙痕固定；林雨层门牌重叠；无时限回退", "beats": [
    {"id": "E02-S02.b01", "sourceLine": 426, "type": "interaction", "kind": "retry", "prompt": "找能区分两趟楼梯的东西。", "options": [{"id": "E02-S02.b01.o1", "label": "只数门上亮着的“一楼”", "sourceLine": 428, "feedback": [{"id": "E02-S02.b01.o1.f1", "type": "line", "sourceLine": 430, "speaker": "动作", "text": "又一次到同一块搪瓷牌前。阿岑在楼下喊了一声，这回从头顶传来。"}], "retry": true}, {"id": "E02-S02.b01.o2", "label": "沿扶手找阿岑系的黑色绕线带", "sourceLine": 432, "feedback": [{"id": "E02-S02.b01.o2.f1", "type": "line", "sourceLine": 434, "speaker": "动作", "text": "第一次绕带在左，第二次右手摸到的是光木头。林雨退回有绕带的一层，墙上多了一道虚掩的饭厅门。"}]}]},
    {"id": "E02-S02.b02", "sourceLine": 436, "type": "line", "speaker": "旁白", "text": "郑福顺用手背碰碰汤碗，试凉热。他把林雨让到下首。墙上奖状旁有四个小小的钉眼，桌上却只有三双短筷子。"},
    {"id": "E02-S02.b03", "sourceLine": 438, "type": "line", "speaker": "旁白", "text": "老人伸手擦桌上一块油印，越擦越亮，照出桌底还有一张更小的桌子，三个男孩正用脚把一只小板凳顶给妹妹坐。林雨低下头，桌底又只是冷的水磨石。"},
    {"id": "E02-S02.b04", "sourceLine": 440, "type": "line", "speaker": "福顺伯", "text": "又少一副？我记得刚才洗了。你让开，我起一下身。"},
    {"id": "E02-S02.b05", "sourceLine": 442, "type": "line", "speaker": "林雨", "text": "我拿。爸……伯，最小这个包放哪里？"},
    {"id": "E02-S02.b06", "sourceLine": 444, "type": "line", "speaker": "福顺伯", "text": "阿梅没下班。我这胳膊够不到她那头，给她留一留。"},
    {"id": "E02-S02.b07", "sourceLine": 446, "type": "line", "speaker": "旁白", "text": "四扇房门浮在汤的热气后面。老二门内响麻将，老三门内响车匙。最里一扇是个头发滴水的姑娘，手里捏着一叠药钱。她托林雨把长子叫回来。"},
    {"id": "E02-S02.b08", "sourceLine": 448, "type": "line", "speaker": "小梅", "text": "你听清楚，我要他自己走回来。你敢把人骗进来，我连你一块儿锁。"}
  ]},
  "E02-S03": {"id": "E02-S03", "chapter": "E02", "title": "长子的店", "next": "E02-S04", "time": "4月4日 傍晚", "place": "门店与楼梯", "cue": "机内只有铁门和空阶；小梅只在林雨视点现身", "beats": [
    {"id": "E02-S03.b01", "sourceLine": 455, "type": "line", "speaker": "阿岑", "text": "你刚才靠在门后面，膝盖都打弯了。我喊了三声你才看我。要不要坐一下？"},
    {"id": "E02-S03.b02", "sourceLine": 457, "type": "line", "speaker": "林雨", "text": "你借我一只耳机。下回你在楼下敲三下，我有地方找你。"},
    {"id": "E02-S03.b03", "sourceLine": 459, "type": "line", "speaker": "旁白", "text": "阿岑把纸袋递还。小包上压出一个拇指印。林雨照小梅的意思，请长子回桌前；同时直说小梅恨他，也说自己没有把握能带他出来。"},
    {"id": "E02-S03.b04", "sourceLine": 461, "type": "line", "speaker": "郑国强", "text": "老二从楼上摔下去，老三撞了石墩。她有没有跟你说？我要是不去呢？"},
    {"id": "E02-S03.b05", "sourceLine": 463, "type": "line", "speaker": "林雨", "text": "那我回去说你不来。屋里还有一把锁，我已经叫罗叔来认。他可以不进去。"},
    {"id": "E02-S03.b06", "sourceLine": 465, "type": "line", "speaker": "旁白", "text": "郑国强从写字台下取出旧工具袋。里面有一把红柄钥匙，藏在一只夹层开线的儿童书包里。"},
    {"id": "E02-S03.b07", "sourceLine": 467, "type": "line", "speaker": "郑国强", "text": "他们两个以前喊我大佬。出事全叫我回来顶。你等我锁铺。我自己去。"},
    {"id": "E02-S03.b08", "sourceLine": 469, "type": "interaction", "kind": "choice", "prompt": "带上楼前，先准备哪一件事？", "options": [{"id": "E02-S03.b08.o1", "label": "请罗叔在外面辨认锁具", "sourceLine": 471, "feedback": [{"id": "E02-S03.b08.o1.f1", "type": "line", "sourceLine": 473, "speaker": "罗叔", "text": "那门有内外两面，拍的时候把铰链拍进来。只看个锁头，我认不出哪个房。"}]}, {"id": "E02-S03.b08.o2", "label": "和阿岑约好退路", "sourceLine": 475, "feedback": [{"id": "E02-S03.b08.o2.f1", "type": "line", "sourceLine": 477, "speaker": "阿岑", "text": "我在外面等你。听见三下就找绕线带；你再舍不得桌上那口饭，也要回一声。"}]}]}
  ]},
  "E02-S04": {"id": "E02-S04", "chapter": "E02", "title": "门外的锁", "next": "E02-S05", "time": "4月4日 入夜", "place": "饭厅与真实地下室门口", "cue": "现实行动先通报；空桌只留物件作声", "beats": [
    {"id": "E02-S04.b01", "sourceLine": 484, "type": "line", "speaker": "旁白", "text": "国强走到父亲旧屋才停下。两双湿脚印穿过他的脚尖，他往后缩，小梅站到了那把红柄钥匙旁。林雨问他愿不愿等民警一起来查。国强点头。接到林雨关于失踪老人房间的线索后，辖区民警到场查看，国强亲手开外门。阿岑待在门外，把时间和位置记在手机上。"},
    {"id": "E02-S04.b02", "sourceLine": 486, "type": "line", "speaker": "旁白", "text": "门内有一张空药板，鞋底蹭过的水泥白印从床边一直拖到门背后。门上锁环伸向过道，屋内向外摸，摸不到。"},
    {"id": "E02-S04.b03", "sourceLine": 488, "type": "interaction", "kind": "inspect", "prompt": "进到饭厅重叠的门槛。在同一个朝向看锁和报纸。", "options": [{"id": "E02-S04.b03.o1", "label": "核对内侧摸得到什么", "sourceLine": 490, "feedback": [{"id": "E02-S04.b03.o1.f1", "type": "line", "sourceLine": 492, "speaker": "林雨", "text": "我手伸直才到门缝。罗叔，锁眼在你那面？"}, {"id": "E02-S04.b03.o1.f2", "type": "line", "sourceLine": 494, "speaker": "罗叔", "text": "在我这面。哪天挂的、谁挂的，别写我见过。"}]}, {"id": "E02-S04.b03.o2", "label": "让国强认照护簿的日期", "sourceLine": 496, "feedback": [{"id": "E02-S04.b03.o2.f1", "type": "line", "sourceLine": 498, "speaker": "郑国强", "text": "这个月三十一天，我写到三十。你往前翻，三个整月都少一天。我在店里一次填完的。"}]}]},
    {"id": "E02-S04.b04", "sourceLine": 500, "when": "E02-S03.b08.o1", "type": "line", "speaker": "旁白", "text": "罗叔把手机放在外侧地面，画里收进铰链和过道。后来有人只转了锁头的特写，他还留着这张全的。"},
    {"id": "E02-S04.b05", "sourceLine": 502, "when": "E02-S03.b08.o2", "type": "line", "speaker": "旁白", "text": "阿岑照约敲响扶手。这次林雨马上回了三下；国强以为父亲在地下回答他，松手后才发现自己一直攥着钥匙。"},
    {"id": "E02-S04.b06", "sourceLine": 504, "type": "line", "speaker": "旁白", "text": "国平的空椅往后响。国安的碗自己翻了个底。林雨听见两个人说都听到过楼板下的敲门声，都以为明天轮到别人来接。"},
    {"id": "E02-S04.b07", "sourceLine": 506, "type": "line", "speaker": "小梅", "text": "爸，哥们都在。今天你还给他留大的？"},
    {"id": "E02-S04.b08", "sourceLine": 508, "type": "line", "speaker": "福顺伯", "text": "他抢惯了，先拿走，别压坏你的。"},
    {"id": "E02-S04.b09", "sourceLine": 510, "type": "line", "speaker": "小梅", "text": "你每回都这样。"},
    {"id": "E02-S04.b10", "sourceLine": 512, "type": "line", "speaker": "福顺伯", "text": "我记得你不吃肥的。这个给你。我分完了，你们有话自己说，别拿我的话替谁答。"},
    {"id": "E02-S04.b11", "sourceLine": 514, "type": "line", "speaker": "旁白", "text": "国强跪在门槛外，没去碰包子。"},
    {"id": "E02-S04.b12", "sourceLine": 516, "type": "line", "speaker": "郑国强", "text": "门是我锁的。说他自己走丢也是我说的。卖楼的人催我证明他没住在这里，我拿那本假簿子应了两头。我知道他还在里边。"},
    {"id": "E02-S04.b13", "sourceLine": 518, "type": "line", "speaker": "旁白", "text": "小梅把钥匙举到他眼前，手指松开。钥匙实实在在落在水泥上，一声就停。她让开了出口。"},
    {"id": "E02-S04.b14", "sourceLine": 520, "type": "line", "speaker": "郑国强", "text": "林小姐，把我刚才的话再问一遍。对着外面的人问。"}
  ]},
  "E02-S05": {"id": "E02-S05", "chapter": "E02", "title": "有人还能作证", "next": "E03-S01", "time": "4月5日至4月12日", "place": "郑家巷口与302", "cue": "人声录音回放清晰；现实手续用日期跳切", "beats": [
    {"id": "E02-S05.b01", "sourceLine": 527, "type": "line", "speaker": "旁白", "text": "民警在门外记下国强当面所说。林雨只就自己当天看到的门和动作作说明。之后家属告诉她已交出照护簿。受邀核对的初步检验摘录中，检材里见到棉絮和鼠药诱饵碎屑，未见正常食物。林雨读到棉絮，把记着“四个包”的纸巾翻了一面，压平，又翻回来。她能确认有人长期被关着、长子承认落锁；死亡经过的调查还在继续。回执在家属手中。国强准她留一段本人自述供核对，拒绝上节目。她当他的面记下两项用途。"},
    {"id": "E02-S05.b02", "sourceLine": 529, "type": "set", "text": "郑家私人核对材料", "record": "zheng", "scope": "private", "holder": "郑家", "detail": "自述及初步检验只供私下核对，家属保管回执。"},
    {"id": "E02-S05.b03", "sourceLine": 531, "type": "line", "speaker": "旁白", "text": "林雨在门口搁下四个新包。饭厅短暂亮起来。桌子变回一张挤手的小方桌，小梅揪走大哥包子尖上的面皮，伸手去接父亲端不动的汤。她仍没看大哥。"},
    {"id": "E02-S05.b04", "sourceLine": 533, "type": "line", "speaker": "小梅", "text": "你写他最后那顿饭的时候，别说他胃口好。他牙都松了，吃硬的疼。"},
    {"id": "E02-S05.b05", "sourceLine": 535, "type": "line", "speaker": "林雨", "text": "我记住了。你那个包子，我问过阿琴，肥的她挑掉了。"},
    {"id": "E02-S05.b06", "sourceLine": 537, "type": "line", "speaker": "小梅", "text": "我早就能吃肥的了。"},
    {"id": "E02-S05.b07", "sourceLine": 539, "type": "line", "speaker": "旁白", "text": "门从里面合上。大哥一个人坐在现实的门槛上，包子在手里，直到凉透也没吃一口。"},
    {"id": "E02-S05.b08", "sourceLine": 541, "type": "line", "speaker": "旁白", "text": "阿岑给《夜访》的工作伙伴沈嘉打电话。她正替一家旧栏目做授权清点，听说他们在棠西，想起一段拍在星火网吧的旧采访。她把已公开的节目名发过来，让他们自己去问原采访者。302电视里，有只鼠标一下一下地撞桌沿。"}
  ]},
  "E03-S01": {"id": "E03-S01", "chapter": "E03", "title": "十七号开机", "next": "E03-S02", "time": "4月16日 夜", "place": "星火网吧", "cue": "机排深处一盏蓝灯；旧招牌已断电", "beats": [
    {"id": "E03-S01.b01", "sourceLine": 552, "type": "line", "speaker": "旁白", "text": "公开节目里，母亲说儿子让网吧耽误了。节目给梁安打的字幕是“少年班神童”。沈嘉说原采访的陈姐肯接电话，但老带子需要找。林雨把手机装兜，跟阿岑上铁梯。"},
    {"id": "E03-S01.b02", "sourceLine": 554, "type": "line", "speaker": "老邓", "text": "我把楼租给人放货了。十七号机还在，搬它费腰。我带你进去，半个钟头，再久你替我点货。"},
    {"id": "E03-S01.b03", "sourceLine": 556, "type": "line", "speaker": "旁白", "text": "阿岑摸到主机插头，插脚上积了灰。林雨眼前的显示器亮起来。一个穿大西服的男孩先踢了踢隔壁椅子。"},
    {"id": "E03-S01.b04", "sourceLine": 558, "type": "line", "speaker": "梁安", "text": "坐这把。那把腿松了，我朋友一坐准翻。"},
    {"id": "E03-S01.b05", "sourceLine": 560, "type": "line", "speaker": "林雨", "text": "你朋友多重啊？"},
    {"id": "E03-S01.b06", "sourceLine": 562, "type": "line", "speaker": "梁安", "text": "你坐一次就知道了。"},
    {"id": "E03-S01.b07", "sourceLine": 564, "type": "line", "speaker": "旁白", "text": "阿岑在她身后接住差点摔倒的空椅子。他看不到递椅子的手，听见椅背朝哪边擦地。"},
    {"id": "E03-S01.b08", "sourceLine": 566, "type": "line", "speaker": "梁安", "text": "你守一下十七号。我刚刚好像又没赶上。他们在屏幕上骂我，只有最后几行，前面我看不到。"}
  ]},
  "E03-S02": {"id": "E03-S02", "chapter": "E03", "title": "答应过的十分钟", "next": "E03-S03", "time": "4月16日 深夜", "place": "网吧异境与家门", "cue": "林雨可见纸面；相机看到合着的旧本；无追逐倒计时", "beats": [
    {"id": "E03-S02.b01", "sourceLine": 573, "type": "line", "speaker": "旁白", "text": "屏幕反光里有一张孩子的书桌。每道题都批了勾，“做完玩十分钟”写了三次，日期也往后改了三次。门外的人叫他把字写清楚一点。"},
    {"id": "E03-S02.b02", "sourceLine": 575, "type": "line", "speaker": "梁安", "text": "上回我写完，也没人说我能出门。你别扯门把，外面会以为是我。"},
    {"id": "E03-S02.b03", "sourceLine": 577, "type": "interaction", "kind": "choice", "prompt": "怎样让门里的人知道你还在？", "options": [{"id": "E03-S02.b03.o1", "label": "在门底轻碰两下", "sourceLine": 579, "feedback": [{"id": "E03-S02.b03.o1.f1", "type": "line", "sourceLine": 581, "speaker": "动作", "text": "里面也回了两下。门外催作业的声音学不会这个节奏。"}, {"id": "E03-S02.b03.o1.f2", "type": "line", "sourceLine": 583, "speaker": "梁安", "text": "这句只有我和你听见。替我问一声，我没来那晚他们等到几点？"}]}, {"id": "E03-S02.b03.o2", "label": "坐在门边等他先开口", "sourceLine": 585, "feedback": [{"id": "E03-S02.b03.o2.f1", "type": "line", "sourceLine": 587, "speaker": "动作", "text": "里面的呼吸从两短一长慢慢平下来。一根手指摸出门缝，蜷着，没让她拉。"}, {"id": "E03-S02.b03.o2.f2", "type": "line", "sourceLine": 589, "speaker": "梁安", "text": "半糖、胖虎、过弯、木头。要是他们真骂我，你别替他们改。"}]}]},
    {"id": "E03-S02.b04", "sourceLine": 591, "type": "line", "speaker": "林雨", "text": "找不齐我也回来告诉你。给我留哪把椅子？"},
    {"id": "E03-S02.b05", "sourceLine": 593, "type": "line", "speaker": "梁安", "text": "你坐裂的。谁叫你刚才笑。"},
    {"id": "E03-S02.b06", "sourceLine": 595, "type": "line", "speaker": "旁白", "text": "阿岑从门外敲三声，林雨回敲。电脑房还在，男孩已经听不见。老邓端着半杯凉茶，问她真要去找几个已经上班的孩子？"}
  ]},
  "E03-S03": {"id": "E03-S03", "chapter": "E03", "title": "四十二分钟", "next": "E03-S04", "time": "4月17日至18日 白天", "place": "修鞋档与旧网吧柜台", "cue": "实名流水屏蔽他人栏；现实账页能拍", "beats": [
    {"id": "E03-S03.b01", "sourceLine": 602, "type": "line", "speaker": "旁白", "text": "老邓拿出旧上机簿。梁安最后一次结账，四十二分钟。网吧关机后，四个孩子挤在前台等到两点；这是老邓亲口记得的。林雨把两件事分两行记。"},
    {"id": "E03-S03.b02", "sourceLine": 604, "type": "line", "speaker": "陈伯", "text": "他这只鞋我补了两回。椅子高，后跟老碰那根铁管。你拍鞋可以，我脸上有油，今天免了。"},
    {"id": "E03-S03.b03", "sourceLine": 606, "type": "line", "speaker": "黄姨", "text": "那套西服是大人码，肩上空得能装个衣架。当年跟拍的让袖子长点好看，我给他暗缝了两针，回来好拆。你们找他哪件事？"},
    {"id": "E03-S03.b04", "sourceLine": 608, "type": "line", "speaker": "阿岑", "text": "有句话剪掉了，我们想问拍的人手里还有没有前后那段。"},
    {"id": "E03-S03.b05", "sourceLine": 610, "type": "line", "speaker": "黄姨", "text": "先过去让胖虎卸完货。骑车的人手机响个不停，别人说什么他都点头，你别当他答应了。"},
    {"id": "E03-S03.b06", "sourceLine": 612, "type": "interaction", "kind": "inspect", "prompt": "核对网上三版采访是不是三位证人。", "options": [{"id": "E03-S03.b06.o1", "label": "按掉笔声同步三个视频", "sourceLine": 614, "feedback": [{"id": "E03-S03.b06.o1.f1", "type": "line", "sourceLine": 616, "speaker": "声画", "text": "三版画幅、标题都不同。同一支笔落在同一块地砖上，画面都在梁安抬头时切走。"}]}, {"id": "E03-S03.b06.o2", "label": "按袖口的两针和镜边破损对齐", "sourceLine": 618, "feedback": [{"id": "E03-S03.b06.o2.f1", "type": "line", "sourceLine": 620, "speaker": "声画", "text": "同样的松线、同样的缺角。三段来自同一条采访。剪口后发生什么，账本和剪辑都答不出来。"}]}]},
    {"id": "E03-S03.b07", "sourceLine": 622, "type": "line", "speaker": "旁白", "text": "陈姐当面放出原带。父亲把儿子的衣领扣到最上一粒。采访结束，画面先黑下去，麦还在录。"},
    {"id": "E03-S03.b08", "sourceLine": 624, "type": "line", "speaker": "陈姐", "text": "我后来带花去过他家。他爸把这套西装洗了，说要退给借衣服的人。桌上那个姓名条还立着。我坐了一会儿，都不知道喊他爸什么。"},
    {"id": "E03-S03.b09", "sourceLine": 626, "type": "line", "speaker": "旧带·梁安", "text": "都拍完了吧？今天能不能让我不当神童？就今天。那件衣服扎我脖子。"},
    {"id": "E03-S03.b10", "sourceLine": 628, "type": "line", "speaker": "陈姐", "text": "这是他活着那天录下来的，你听得见。我留原带，你带时码。给他朋友听可以，别拿去做预告。"},
    {"id": "E03-S03.b11", "sourceLine": 630, "type": "set", "text": "旧采访的私听许可", "record": "interview", "scope": "private", "holder": "陈姐／四位朋友", "detail": "陈姐保管原带。旧采访只准给朋友听，账号、截图和孩子的声音不公开。"}
  ]},
  "E03-S04": {"id": "E03-S04", "chapter": "E03", "title": "四个活人", "next": "E03-S05", "time": "4月19日 下班后", "place": "茶饮铺与铁梯", "cue": "线下看本地存档；头盔、杯套、旧盘对到四人", "beats": [
    {"id": "E03-S04.b01", "sourceLine": 637, "type": "line", "speaker": "旁白", "text": "胖虎给客人送错了一袋冰，回来才肯坐。半糖在旁边帮他把湿外卖袋摊开。木头带旧盘，过弯要送最后一单，头盔还没脱。"},
    {"id": "E03-S04.b02", "sourceLine": 639, "type": "line", "speaker": "林雨", "text": "他叫我问，你们后来骂没骂他？"},
    {"id": "E03-S04.b03", "sourceLine": 641, "type": "line", "speaker": "胖虎", "text": "骂了。朝老板骂的。我以为考上少年班就不肯跟咱们坐了。我嘴臭，你别剪掉。"},
    {"id": "E03-S04.b04", "sourceLine": 643, "when": "E03-S02.b03.o1", "type": "line", "speaker": "旁白", "text": "林雨用指节在桌底敲了两下。半糖停住摇杯的手，也回了两下。她说以前上铁梯第一个到的人就这么叫后面的人跟上。"},
    {"id": "E03-S04.b05", "sourceLine": 645, "when": "E03-S02.b03.o2", "type": "line", "speaker": "旁白", "text": "林雨把梁安从门缝下报出的四个旧名逐个念了一遍。胖虎听见“过弯”就往外看，对面那辆电动车果然骑过茶铺又倒了回来。"},
    {"id": "E03-S04.b06", "sourceLine": 647, "type": "line", "speaker": "半糖", "text": "他下午给我发了三次对不住。我那句“明天再打”还在吧？木头，你翻，别拿我现在这号搜。"},
    {"id": "E03-S04.b07", "sourceLine": 649, "type": "line", "speaker": "旁白", "text": "木头的本地副本里，四人等人的消息都在。梁安在异境里反复看到的“你个废物”，现实副本里找不到。谁敲过那行字，四人都说不准。"},
    {"id": "E03-S04.b08", "sourceLine": 651, "type": "line", "speaker": "阿岑", "text": "他留给我一把会塌的椅子。明天我带扳手，你们把人带齐。"},
    {"id": "E03-S04.b09", "sourceLine": 653, "type": "line", "speaker": "过弯", "text": "明天这个点我有单。今晚行不行？反正头盔都脱了。"},
    {"id": "E03-S04.b10", "sourceLine": 655, "type": "line", "speaker": "旁白", "text": "他往里走，头盔还戴着。半糖伸手给他扣了扣护目镜，四个人同时笑了。"}
  ]},
  "E03-S05": {"id": "E03-S05", "chapter": "E03", "title": "五把椅子", "next": "E04-S01", "time": "4月19日 近零点", "place": "星火网吧", "cue": "同一构图切现实与林雨视角；不给录像补画鬼", "beats": [
    {"id": "E03-S05.b01", "sourceLine": 662, "type": "line", "speaker": "旁白", "text": "老邓把四把椅子排好。木头插入旧盘，停在当年的房间。林雨向旁边挪半个身位，留出十七号机。胖虎把没发出去的那句气话亲口说了。过弯把饮料挪远。"},
    {"id": "E03-S05.b02", "sourceLine": 664, "type": "line", "speaker": "梁安", "text": "他老碰倒人家杯子。你问他还记不记得那件事。"},
    {"id": "E03-S05.b03", "sourceLine": 666, "type": "line", "speaker": "过弯", "text": "我当然记得。有一回你替我赔的，欠你三块五。"},
    {"id": "E03-S05.b04", "sourceLine": 668, "type": "line", "speaker": "梁安", "text": "是四块。他记性还是那样。"},
    {"id": "E03-S05.b05", "sourceLine": 670, "type": "interaction", "kind": "choice", "prompt": "让四个人怎么收到这句话？", "options": [{"id": "E03-S05.b05.o1", "label": "替他逐字带话，由梁安按开始", "sourceLine": 672, "feedback": [{"id": "E03-S05.b05.o1.f1", "type": "line", "sourceLine": 674, "speaker": "林雨", "text": "他说，是四块。你少给五毛，他可不干。"}, {"id": "E03-S05.b05.o1.f2", "type": "line", "sourceLine": 676, "speaker": "动作", "text": "过弯摸出四枚硬币，压在键盘角。屏幕上第五个头像总算亮了。"}]}, {"id": "E03-S05.b05.o2", "label": "先让大家安静，让旧鼠标自己响", "sourceLine": 678, "feedback": [{"id": "E03-S05.b05.o2.f1", "type": "line", "sourceLine": 680, "speaker": "动作", "text": "第五只鼠标响了四下。过弯试探着把三块五数到四块，鼠标停了。胖虎扭过脸，笑得鼻音很重。"}]}]},
    {"id": "E03-S05.b06", "sourceLine": 682, "type": "line", "speaker": "梁安", "text": "我想再用我自己的名字玩一局。换回来行吗？"},
    {"id": "E03-S05.b07", "sourceLine": 684, "type": "line", "speaker": "老邓", "text": "你卡还在这儿，带照片那面都卷了。拿去。"},
    {"id": "E03-S05.b08", "sourceLine": 686, "type": "line", "speaker": "旁白", "text": "一局打完，计分没谁顾上看。梁安把卡往柜台推。林雨忽然想起陈姐说过那件洗干净的西装，问他想穿哪件回去。梁安把大外衣一脱，里面是件领口褪白的旧球衣。他拿外套盖在椅背上，好像明天还会回来拿。他起身时把那把好椅让给了阿岑。阿岑继续拧松的那条腿，手忽然顿了一下。"},
    {"id": "E03-S05.b09", "sourceLine": 688, "type": "line", "speaker": "旁白", "text": "林雨最后才问起那几行骂人的字。屏上还留了一行“都怪你”。胖虎说他后来骂过自己，半糖说那天也怨过胖虎。没人见过谁敲进这四个字。梁安把对话框缩小，频道里响起一次很普通的组队邀请，没再把谁关在门外。"},
    {"id": "E03-S05.friends.1", "type": "line", "speaker": "旁白", "text": "阿岑把拍完的一局给他们四个看。画面里，四个人朝一把空椅子笑。半糖把这段拷进木头带来的旧盘，留给几个朋友。", "origin": "outline-bridge"},
    {"id": "E03-S05.b10", "sourceLine": 690, "type": "line", "speaker": "老邓", "text": "采访的录音留在你们自己那儿。你们真要传，传我这句：那天前台有四个人，等他到打烊。我姓邓，我自己说。"},
    {"id": "E03-S05.b11", "sourceLine": 692, "type": "set", "text": "老邓准许公开的证言", "record": "deng", "scope": "public", "holder": "老邓", "detail": "可播本人亲见的等候和经许可的上机时长。"}
  ]},
  "E04-S01": {"id": "E04-S01", "chapter": "E04", "title": "两双筷子", "next": "E04-S02", "time": "4月26日 夜", "place": "粉摊", "cue": "蒸汽、碟底；收银叫号与蒸柜声分开", "beats": [
    {"id": "E04-S01.b01", "sourceLine": 703, "type": "line", "speaker": "旁白", "text": "林雨有一期婚礼精剪交了片，准备续一个月302。她到粉摊吃夜宵，自己记得带现金；粉叔上回说手湿时按不开手机。他撕了两套一次性筷子，拆开一套，另一套压在炉边。"},
    {"id": "E04-S01.b02", "sourceLine": 705, "type": "line", "speaker": "林雨", "text": "我一个人。阿岑今天在酒店拍婚宴。"},
    {"id": "E04-S01.b03", "sourceLine": 707, "type": "line", "speaker": "粉叔", "text": "我知道你一个人。你坐矮一点那张，高的我留给腿不好的人。"},
    {"id": "E04-S01.b04", "sourceLine": 709, "type": "line", "speaker": "旁白", "text": "林雨端着碟绕了一圈才坐下。摊前忽然排了十几个人，蒸笼里明明只有三份肠粉。没人往前挪，只有影子往前走。粉叔专心摊粉。"},
    {"id": "E04-S01.b05", "sourceLine": 711, "type": "line", "speaker": "粉叔", "text": "酱分开、不要葱、工棚那份多浇点。你要肯送，我就早半个钟头收工。就这三份，多的我一个人蒸不来。"},
    {"id": "E04-S01.b06", "sourceLine": 713, "type": "line", "speaker": "旁白", "text": "他接的单子都是以前手写的。价钱那一格是空的。林雨把自己的碟子盖起来，包上的收条夹到一起走。"}
  ]},
  "E04-S02": {"id": "E04-S02", "chapter": "E04", "title": "三份旧单", "next": "E04-S03", "time": "4月27日 01:40", "place": "工棚旧址、桥底、卸货门", "cue": "三格连续画；每处手交食物，收据的空栏保留", "beats": [
    {"id": "E04-S02.b01", "sourceLine": 720, "type": "line", "speaker": "工人", "text": "七十六，是领钱叫的号。我妈要来，你说七十六，她认得哪个？你手底下那张纸借一下。"},
    {"id": "E04-S02.b02", "sourceLine": 722, "type": "interaction", "kind": "choice", "prompt": "在工号之外，留下哪一种可供亲友核对的东西？", "options": [{"id": "E04-S02.b02.o1", "label": "垫好复写纸，把笔让给他", "sourceLine": 724, "feedback": [{"id": "E04-S02.b02.o1.f1", "type": "line", "sourceLine": 726, "speaker": "动作", "text": "工人写“想回来”，最后一笔戳穿薄纸。林雨留副页，原页压回他的安全帽下。对方握笔的手劲只在那张纸上留过一次。"}]}, {"id": "E04-S02.b02.o2", "label": "照他指的位置描下缺瓷的饭缸", "sourceLine": 728, "feedback": [{"id": "E04-S02.b02.o2.f1", "type": "line", "sourceLine": 730, "speaker": "工人", "text": "蓝边，缺的这块像颗松牙。底下是我家的屋号，不要拿到街上念。"}, {"id": "E04-S02.b02.o2.f2", "type": "line", "sourceLine": 732, "speaker": "动作", "text": "林雨折起私人屋号，只把轮廓留在回单外侧。这个工号曾有人代领，单凭它还不能认人。"}]}]},
    {"id": "E04-S02.b03", "sourceLine": 734, "type": "line", "speaker": "代驾", "text": "酱另外装的？好。别在单上盖“送达客人”。我在桥底歇脚，等单的时候睡过去，我哥找不到我。写头盔也在。"},
    {"id": "E04-S02.b04", "sourceLine": 736, "type": "line", "speaker": "林雨", "text": "你哥会认这两个贴纸吗？"},
    {"id": "E04-S02.b05", "sourceLine": 738, "type": "line", "speaker": "代驾", "text": "他给我贴正过三回，还歪。你就留个歪的。"},
    {"id": "E04-S02.b06", "sourceLine": 740, "type": "line", "speaker": "旁白", "text": "女孩坐在卸货门背后，胸卡盖在手心。她手指够不到手机上的发送键。"},
    {"id": "E04-S02.b07", "sourceLine": 742, "type": "line", "speaker": "女孩", "text": "我请病假的事，同事拿去当培训录音了。你在录吗？"},
    {"id": "E04-S02.b08", "sourceLine": 744, "type": "line", "speaker": "林雨", "text": "手机你看得见，在袋子里。你那份没葱。热，小心底下。"},
    {"id": "E04-S02.b09", "sourceLine": 746, "type": "line", "speaker": "旁白", "text": "女孩只把饭盒挪到膝头。林雨等了一会儿，她已低头吃起来。林雨把回单的姓名一栏折到背面，没再问。"}
  ]},
  "E04-S03": {"id": "E04-S03", "chapter": "E04", "title": "多出来的活人", "next": "E04-S04", "time": "4月27日 02:15", "place": "粉摊", "cue": "队尾到队首变化以动作计；危险声可用字幕辨向", "beats": [
    {"id": "E04-S03.b01", "sourceLine": 753, "type": "line", "speaker": "旁白", "text": "回到摊上，那个蓝白耳麦还在队伍里。排在小茵前面的人脚跟离地；小茵的鞋挤破水泡，袜口有血。她手机第三次震，屏幕亮着今晚换班的通知。"},
    {"id": "E04-S03.b02", "sourceLine": 755, "type": "line", "speaker": "小茵", "text": "你能看见我？他们都不理我。排这么久，我以为我也……轮到我喊几号？"},
    {"id": "E04-S03.b03", "sourceLine": 757, "type": "line", "speaker": "旁白", "text": "队首的叫号器从七十六跳到她工号。她已经练惯了，一听见号码就要应答。"},
    {"id": "E04-S03.b04", "sourceLine": 759, "type": "interaction", "kind": "choice", "prompt": "打断下一次叫号，给小茵留一个自己能做的动作。", "options": [{"id": "E04-S03.b04.o1", "label": "问她愿不愿自己摘下耳麦", "sourceLine": 761, "feedback": [{"id": "E04-S03.b04.o1.f1", "type": "line", "sourceLine": 763, "speaker": "小茵", "text": "我摘了就要被记离线的。……我都下班了啊。"}, {"id": "E04-S03.b04.o1.f2", "type": "line", "sourceLine": 765, "speaker": "动作", "text": "她自己把耳麦放进饭碗旁，先听见蒸柜的水在烧，才听见有人叫她名字。"}]}, {"id": "E04-S03.b04.o2", "label": "请阿琴开侧门，让她认出回家的路", "sourceLine": 767, "feedback": [{"id": "E04-S03.b04.o2.f1", "type": "line", "sourceLine": 769, "speaker": "阿琴", "text": "茵茵，你昨天落在柜上那包纸巾，还要我送回去呀？"}, {"id": "E04-S03.b04.o2.f2", "type": "line", "sourceLine": 771, "speaker": "动作", "text": "小茵回头，离开队伍半步，胸前那只工号牌仍在原地晃。她把挂带从脖子上脱下来。"}]}]},
    {"id": "E04-S03.b05", "sourceLine": 773, "type": "line", "speaker": "旁白", "text": "粉叔把压住的两根筷子推到她手边，转过身调火。林雨把没动的那碟掀开。小茵咬得慢，吃到第二口才发觉已经凉了。"},
    {"id": "E04-S03.b06", "sourceLine": 775, "type": "line", "speaker": "小茵", "text": "你们那行，拍人出事才有钱吧？我今晚上只想回去睡。有没有人要拍我这副相？"},
    {"id": "E04-S03.b07", "sourceLine": 777, "type": "line", "speaker": "林雨", "text": "只有我在这儿吃剩粉。你要不要一起重新蒸一下？"},
    {"id": "E04-S03.b08", "sourceLine": 779, "type": "line", "speaker": "旁白", "text": "小茵把自己的碟子叠上来。队伍退回棚边。她刚才站的位置上，短暂地出现了另一个端着外卖盒的林雨，还在等一个工单提示。林雨往后退一步，那个人却往前走了一步，把下一个号举到胸前。粉叔撂下碟子。"},
    {"id": "E04-S03.b09", "sourceLine": 781, "type": "line", "speaker": "粉叔", "text": "你说你还差一件事。是哪样？你不说它，它就替你一直等。"},
    {"id": "E04-S03.b10", "sourceLine": 783, "type": "line", "speaker": "林雨", "text": "我饭还没吃完。麻烦退个位。"},
    {"id": "E04-S03.b11", "sourceLine": 785, "type": "line", "speaker": "旁白", "text": "队里的林雨侧过身来。她脸上没有眼睛，只有旧手机熄屏时留下的两点指印。林雨端着碟从摊外回到矮凳。小茵把手机翻过来，两个人面朝同一碟还有点温的酱汁。"}
  ]},
  "E04-S04": {"id": "E04-S04", "chapter": "E04", "title": "有人来问", "next": "E05-S01", "time": "4月27日 天亮", "place": "粉摊与302", "cue": "街坊陆续上早班；手机来电可读", "beats": [
    {"id": "E04-S04.b01", "sourceLine": 792, "type": "line", "speaker": "旁白", "text": "粉叔摊开本子，给每个有信儿的人夹个小铁夹。送工服的女人说七十六可能有人替领，蓝边饭缸也借给过别人。林雨把她的联系电话递给粉叔，当面记下“有人来问”。那格姓名仍空着。"},
    {"id": "E04-S04.b02", "sourceLine": 794, "when": "E04-S02.b02.o1", "type": "line", "speaker": "旁白", "text": "女人摸过复写上的“回”字，说弟弟写字也这样用力。她愿意回去拿旧信比一比。"},
    {"id": "E04-S04.b03", "sourceLine": 796, "when": "E04-S02.b02.o2", "type": "line", "speaker": "旁白", "text": "女人认得饭缸的颜色，也记得它借给过别人。她把轮廓带回给亲属，一个名字也没急着填。"},
    {"id": "E04-S04.b04", "sourceLine": 798, "type": "line", "speaker": "粉叔", "text": "本子放我这儿，找人的能来。你要照就照页码，电话藏我手底下。以后我不出摊，你带人来问我儿子。"},
    {"id": "E04-S04.b05", "sourceLine": 800, "type": "set", "text": "粉摊回单页码", "record": "orders", "scope": "private", "holder": "粉叔", "detail": "只记页码；家属仍在核对，姓名和夹板内的电话不对外。"},
    {"id": "E04-S04.b06", "sourceLine": 802, "type": "line", "speaker": "林雨", "text": "我不是刚往你这儿送了三份？你怎么又给我整了一碟？"},
    {"id": "E04-S04.b07", "sourceLine": 804, "type": "line", "speaker": "粉叔", "text": "你那碟都放几遍了。我怕你吃完上网写我技术不好。加不加葱？"},
    {"id": "E04-S04.b08", "sourceLine": 806, "type": "line", "speaker": "林雨", "text": "多点。下礼拜换我看炉子，你去理个发。"},
    {"id": "E04-S04.b09", "sourceLine": 808, "type": "line", "speaker": "手机·阿岑", "text": "喜酒喝了半盏，酒店老板想找人做夏季栏目。问了我《夜访》三回。周铭，星环的，名片拍给你。还有，房租我转节目账户了，你先续，慢慢剪。"},
    {"id": "E04-S04.b10", "sourceLine": 810, "type": "line", "speaker": "旁白", "text": "小茵发来一张自家门里拍的拖鞋照片，让林雨知道她到了。林雨按约去老许处续租，账上记到5月27日。小茵敲下的最后一条语音没头没尾——“葱不用留给我，下次我自己来讲。”"},
    {"id": "E04-S04.visit.1", "type": "line", "speaker": "旁白", "text": "后来小茵也会下了班上三楼，敲两下门。有一晚她只借了个充电头，在床边坐了五分钟就走了。", "origin": "outline-bridge"}
  ]},
  "E05-S01": {"id": "E05-S01", "chapter": "E05", "title": "周三可以", "next": "E05-S02", "time": "5月8日 19:30", "place": "302剪辑桌", "cue": "真实商业试剪；手机讯息与素材回放分轨", "beats": [
    {"id": "E05-S01.b01", "sourceLine": 821, "type": "line", "speaker": "旁白", "text": "周铭想为年轻人夜班生活做一期节目。开样片付三千六，发布另谈。团队接下有偿试剪，约定公开素材逐项授权，正式成片交付前两个人一起看。沈嘉负责找受访者签试剪用途。周铭把合同和四段采访一并发来。"},
    {"id": "E05-S01.b02", "sourceLine": 823, "type": "line", "speaker": "周铭", "text": "你们有个好处。棚里主持人说辛苦，别人信他通告费高。你在楼上剪片，人家知道你明天还欠着房租。"},
    {"id": "E05-S01.b03", "sourceLine": 825, "type": "line", "speaker": "录音·仓管员", "text": "周三我可以加班。下礼拜得接我妹，我妈回老家复查眼睛。"},
    {"id": "E05-S01.b04", "sourceLine": 827, "type": "line", "speaker": "手机·试剪意见", "text": "“我可以加班”后接清晨镜头。片尾暂用频道公开的三巷雨景。"},
    {"id": "E05-S01.b05", "sourceLine": 829, "type": "line", "speaker": "阿岑", "text": "明早得还那支长镜头。单子真下来我就能换成自己的。她后面半句你留上，时长我跟人家讲。"},
    {"id": "E05-S01.b06", "sourceLine": 831, "type": "line", "speaker": "旁白", "text": "林雨去楼顶收衣，洗衣篮里只剩一件干衬衫。她回头想拍晚霞给妈妈，天已经暗了。照片里只有一块挂满湿衣服的楼顶。"}
  ]},
  "E05-S02": {"id": "E05-S02", "chapter": "E05", "title": "口袋里的钟", "next": "E05-S03", "time": "5月8日 夜", "place": "楼顶绳阵", "cue": "滴水变成鼠标声；风动方向固定；没有实体坠落镜头", "beats": [
    {"id": "E05-S02.b01", "sourceLine": 838, "type": "line", "speaker": "旁白", "text": "四件湿工装把绳子拉到了腰际。窗后透出显示器的蓝光，工位间隔恰好是一根绳那么长。一件卫衣伸出袖口按鼠标，一次比一次慢。"},
    {"id": "E05-S02.b02", "sourceLine": 840, "type": "line", "speaker": "林雨", "text": "我就拿我的衬衫。你……要我帮你挂高点？"},
    {"id": "E05-S02.b03", "sourceLine": 842, "type": "line", "speaker": "旁白", "text": "袖子颤了一下。林雨翻开衣袋。一张折了三折的辞职草稿，落款已经签好。游标停在“发送”，盯得久了，手机里也出现同一个窗口。"},
    {"id": "E05-S02.b04", "sourceLine": 844, "type": "interaction", "kind": "choice", "prompt": "试着替空工位处理一张返单。", "options": [{"id": "E05-S02.b04.o1", "label": "写明原采访只答应周三", "sourceLine": 846, "feedback": [{"id": "E05-S02.b04.o1.f1", "type": "line", "sourceLine": 848, "speaker": "屏显", "text": "“周三”被系统自动铺满一周七格。林雨手动擦掉另外六个，袖口松了一寸。"}]}, {"id": "E05-S02.b04.o2", "label": "把接妹妹的后半句接回去", "sourceLine": 850, "feedback": [{"id": "E05-S02.b04.o2.f1", "type": "line", "sourceLine": 852, "speaker": "声画", "text": "仓管员的声音说完了，屏幕的催办红灯还亮着。一只手从另一侧伸来，将那一条拖回本人收件箱。"}]}]},
    {"id": "E05-S02.b05", "sourceLine": 854, "type": "line", "speaker": "林雨", "text": "这些是谁交给谁的？我再帮你做完一单，你明早就能回去？"},
    {"id": "E05-S02.b06", "sourceLine": 856, "type": "line", "speaker": "旁白", "text": "墙后的人低着头没回答。四件衣服口袋里的纸条一齐冲她这边翻过来。上面有四个不同的收件人。"}
  ]},
  "E05-S03": {"id": "E05-S03", "chapter": "E05", "title": "四个收件窗", "next": "E05-S04", "time": "5月8日 深夜", "place": "楼顶与收件窗", "cue": "四次交件按物件确认；衣料落下给空间腾出路", "beats": [
    {"id": "E05-S03.b01", "sourceLine": 863, "type": "interaction", "kind": "retry", "prompt": "四个投递窗只有一个能给工资明细退回有日期的凭条。", "options": [{"id": "E05-S03.b01.o1", "label": "投到写着“优秀员工”的表扬栏", "sourceLine": 865, "feedback": [{"id": "E05-S03.b01.o1.f1", "type": "line", "sourceLine": 867, "speaker": "动作", "text": "纸给玻璃弹回，折角上添了一颗笑脸贴纸。雨衣还在抖水，数字一个也没有被登记。"}], "retry": true}, {"id": "E05-S03.b01.o2", "label": "打开申诉收件窗，留下工资单副本", "sourceLine": 869, "feedback": [{"id": "E05-S03.b01.o2.f1", "type": "line", "sourceLine": 871, "speaker": "声画", "text": "窗里有人接住，在复写页压下日期戳。柜面向她这边退了一格。"}]}]},
    {"id": "E05-S03.b02", "sourceLine": 873, "type": "line", "speaker": "旁白", "text": "骑手雨衣的口袋里是一张工资明细，日期和数额抄了两遍。刚才递进申诉窗的那一页已经有了回执，雨衣袖管扁了。受理回条上的日期是旧年的。现实里的人还须自己去找这份材料。"},
    {"id": "E05-S03.b03", "sourceLine": 875, "type": "line", "speaker": "旁白", "text": "程序员的卫衣轮到窗前。有一只手按住辞职草稿的签名，示意她松手。它自己把前面四段客套删了，只留下落款和生效日期，自己按了发送。"},
    {"id": "E05-S03.b04", "sourceLine": 877, "type": "line", "speaker": "林雨", "text": "还以为你让我替你辞。"},
    {"id": "E05-S03.b05", "sourceLine": 879, "type": "line", "speaker": "窗后声音", "text": "删这几段我练了三年。差你替我点那一下吗？"},
    {"id": "E05-S03.b06", "sourceLine": 881, "type": "line", "speaker": "旁白", "text": "保安的耳机电池仓里藏着邮费。林雨只写到县名，衣袖自己在地址下面添上一个小组号，把旧耳机送回家。最后一窗等一个蛋糕，妹妹在里面摆好两只碟。林雨捡出盒绳里卡住的蓝蜡烛。"},
    {"id": "E05-S03.b07", "sourceLine": 883, "type": "line", "speaker": "窗里的妹妹", "text": "姐还在忙啊？她要是只歇五分钟，你别催她打电话。让她先吃。"},
    {"id": "E05-S03.b08", "sourceLine": 885, "type": "line", "speaker": "旁白", "text": "林雨没说自己见到的是一件空衣服。她隔着窗帮妹妹扶了一下纸碟边。四张回执留在湿玻璃上。镜头回现实，她手上只有一截旧夹子。"}
  ]},
  "E05-S04": {"id": "E05-S04", "chapter": "E05", "title": "署名栏", "next": "E05-S05", "time": "5月9日 凌晨", "place": "楼顶与302", "cue": "阿岑能听金属夹响；现实群聊用手机画面", "beats": [
    {"id": "E05-S04.b01", "sourceLine": 892, "type": "line", "speaker": "旁白", "text": "工作手机连响两次。试剪预览里，福顺伯旧屋的空门被接到孩子噤声的黑屏后面，两者都是周铭团队给的气氛镜头；没有一个死者在画面里。片尾是林雨的名字。"},
    {"id": "E05-S04.b02", "sourceLine": 894, "type": "line", "speaker": "阿岑", "text": "我刚看见别人加了这两刀。你还在屋顶？你走了一个多小时。左手敲一下晾衣杆，能听见我就再敲。"},
    {"id": "E05-S04.b03", "sourceLine": 896, "type": "line", "speaker": "林雨", "text": "听见了。那两刀放在一起，就像是那个孩子死在那间屋。我们什么时候点的头？"},
    {"id": "E05-S04.b04", "sourceLine": 898, "type": "line", "speaker": "手机·周铭", "text": "样片现在只给订户看方案，跟公开发行是两笔账。暂时不上线，今晚先过，不合适可以改。尾款月底给你们走。"},
    {"id": "E05-S04.b05", "sourceLine": 900, "type": "interaction", "kind": "choice", "prompt": "留下哪一种处理记录？", "options": [{"id": "E05-S04.b05.o1", "label": "在项目群署名说明两处错接，拒交此版", "sourceLine": 902, "feedback": [{"id": "E05-S04.b05.o1.f1", "type": "line", "sourceLine": 904, "speaker": "手机·林雨", "text": "两个地点、两个人。我不交现在这一版。署名林雨。仓管员只答应周三。"}, {"id": "E05-S04.b05.o1.f2", "type": "line", "sourceLine": 906, "speaker": "阿岑", "text": "行，我也留名字。你把饭热了，电话我跟他打。"}]}, {"id": "E05-S04.b05.o2", "label": "撤回导出，私下把正确的整段交给阿岑", "sourceLine": 908, "feedback": [{"id": "E05-S04.b05.o2.f1", "type": "line", "sourceLine": 910, "speaker": "动作", "text": "林雨取消导出，把新的时间线传给阿岑。项目群停在“对方正在输入”，始终没有公开的拒剪记录。"}, {"id": "E05-S04.b05.o2.f2", "type": "line", "sourceLine": 912, "speaker": "阿岑", "text": "好，文件我收到了。后面要是他拿咱们名字说事，只有咱俩知道当时讲过什么。"}]}]},
    {"id": "E05-S04.b06", "sourceLine": 914, "when": "E05-S02.b04.o1", "type": "line", "speaker": "旁白", "text": "林雨给仓管员发出带时码的文字。对方回了一个“是周三”，隔了半小时又发来一张小孩乱画的周历，星期三被蓝笔圈得滚圆。"},
    {"id": "E05-S04.b07", "sourceLine": 916, "when": "E05-S02.b04.o2", "type": "line", "speaker": "旁白", "text": "重听整段录音时，阿岑才听见女孩结尾在问摄影师饿不饿。他给她留了这几秒的私人副本。她说回头给妹妹听，妹妹一直以为她在电视台上班。"},
    {"id": "E05-S04.b08", "sourceLine": 918, "type": "line", "speaker": "旁白", "text": "衣绳在门外啪嗒落了一根。林雨推开楼顶门，老许抱着落下来的一床被单，肩上别着两只木夹。"},
    {"id": "E05-S04.b09", "sourceLine": 920, "type": "line", "speaker": "老许", "text": "看手机就别卡在门里。我这盆水都端酸了。两杯豆浆，一甜一淡，你记不记得你拿的哪杯？"},
    {"id": "E05-S04.b10", "sourceLine": 922, "type": "line", "speaker": "林雨", "text": "您怎么知道我在这儿？"},
    {"id": "E05-S04.b11", "sourceLine": 924, "type": "line", "speaker": "老许", "text": "我不知道。我自己喝一杯，另一个本来是给补鞋的。他说喝了夜里得起两趟。"}
  ]},
  "E05-S05": {"id": "E05-S05", "chapter": "E05", "title": "工钱", "next": "E06-S01", "time": "5月9日 早晨", "place": "三巷早摊", "cue": "拍摄暂停；电话里菜刀和砧板留完整一拍", "beats": [
    {"id": "E05-S05.b01", "sourceLine": 931, "type": "line", "speaker": "妈妈", "text": "片子弄完了吗？我买了豆角，等下晒一盘。"},
    {"id": "E05-S05.b02", "sourceLine": 933, "type": "line", "speaker": "林雨", "text": "差两刀。我没交。人家要是找别人，这个月给你的钱得晚几天。"},
    {"id": "E05-S05.b03", "sourceLine": 935, "type": "line", "speaker": "妈妈", "text": "那就晚几天。你姨上次欠我的麻将钱还没给，我去催她。你甭笑，她赢的时候收得可快了。"},
    {"id": "E05-S05.b04", "sourceLine": 937, "type": "line", "speaker": "旁白", "text": "阿岑用一份设备出租的收入先还掉本月镜头费。团队只结了已完成的工时，余下款项重谈。两个人吃完早点，林雨才发现老许拿来那两杯都是淡的。桌对面压着旧招租单，印着“近厂、有窗、八百”，窗户照片里却有条水印。有人在《夜访》社群问这房子是不是还在租，他晚上就要看房。"},
    {"id": "E05-S05.sister.1", "type": "line", "speaker": "旁白", "text": "那天，林雨挨家问屋顶上那件旧工装，最后把自己的电话号码留给了姐姐的老同事。几天后妹妹打来，听她提起没送到的生日蛋糕，想了半天，也记不起是哪一年的生日。", "origin": "outline-bridge"},
    {"id": "E05-S05.sister.2", "type": "line", "speaker": "妹妹", "text": "她在广州那阵，有没有一到休息就约来吃饭的朋友？有没有哪天玩得高兴，舍不得回去？", "origin": "outline-bridge"},
    {"id": "E05-S05.sister.3", "type": "line", "speaker": "林雨", "text": "这个我真的不知道。", "origin": "outline-bridge"}
  ]},
  "E06-S01": {"id": "E06-S01", "chapter": "E06", "title": "墙里有人游泳", "next": "E06-S02", "time": "5月22日 傍晚", "place": "三巷十二号后楼", "cue": "雨季；同一扇窗分室外广告、室内高窗两个角度", "beats": [
    {"id": "E06-S01.b01", "sourceLine": 948, "type": "line", "speaker": "旁白", "text": "屋里听得到一下一下蹬壁声。楼后早已改作储物用的半地下层，外墙糊着一张新招租纸。社群里的青年刚到广州，私下给转租人付了押金，对方叫他晚上来领钥匙。老许认得广告上的高窗。这一个月团队几乎天天在村里，林雨提前续房到6月27日，租约就在同一个文件袋里。别人打算在这样的屋里住一个月，和她当初问302一样，也都先问总共要付多少押金。"},
    {"id": "E06-S01.b02", "sourceLine": 950, "type": "line", "speaker": "老许", "text": "隔板是我年轻时帮忙抬下去的。给钱，我就抬。后来雨灌进去，报纸照片上我认出了自己抬的那一块。"},
    {"id": "E06-S01.b03", "sourceLine": 952, "type": "line", "speaker": "林雨", "text": "你那时候知道那儿住人吗？"},
    {"id": "E06-S01.b04", "sourceLine": 954, "type": "line", "speaker": "老许", "text": "头一趟不知道。第二趟有人叫我给他留条能摆电饭锅的边。我知道了。你要记就两趟都记。"},
    {"id": "E06-S01.b05", "sourceLine": 956, "type": "line", "speaker": "旁白", "text": "罗叔来辨门。阿岑沿楼梯看排水，林雨和新租客隔着栏杆对了一遍房号，发现对方收到的室内图裁去了高窗下方大半堵墙。"},
    {"id": "E06-S01.b06", "sourceLine": 958, "type": "line", "speaker": "新租客", "text": "我妈给我装了两瓶炒辣椒。我答应给她看做饭的灶台。中介只给我看插座，我也没敢多问。"}
  ]},
  "E06-S02": {"id": "E06-S02", "chapter": "E06", "title": "水线", "next": "E06-S03", "time": "5月22日 入夜", "place": "半地下层入口", "cue": "林雨视点是鱼缸；现实视点为旧隔板；响雷后镜头不闪白", "beats": [
    {"id": "E06-S02.b01", "sourceLine": 965, "type": "line", "speaker": "旁白", "text": "一名男人拎着水桶站在早已封住的三号门里。他说自己叫阿良，是老许说的那个知道哪一处先漏水的人。他夜里还在一格一格敲玻璃，想把当年没听见警告的人叫起来。"},
    {"id": "E06-S02.b02", "sourceLine": 967, "type": "line", "speaker": "阿良", "text": "柜顶搁药。水往上爬得比你搬东西快。你站外面看干什么？里面还有五张床没叫。"},
    {"id": "E06-S02.b03", "sourceLine": 969, "type": "line", "speaker": "旁白", "text": "林雨往前一步，陆地上的走道在她眼里变成水缸之间的缝。有人从玻璃后瞪着她，嘴张得很大，听不到。新租客只看见天花板在滴水，拖箱往有灯的缓台上走。"},
    {"id": "E06-S02.b04", "sourceLine": 971, "type": "interaction", "kind": "retry", "prompt": "辨认往年洪水的痕迹。", "options": [{"id": "E06-S02.b04.o1", "label": "对齐正在晃动的亮边", "sourceLine": 973, "feedback": [{"id": "E06-S02.b04.o1.f1", "type": "line", "sourceLine": 975, "speaker": "动作", "text": "那线随手电移动。新租客关掉手电，亮边消失，墙面仍有一条粗痕。"}], "retry": true}, {"id": "E06-S02.b04.o2", "label": "把床垫泥边和墙上沙粒连成一线", "sourceLine": 977, "feedback": [{"id": "E06-S02.b04.o2.f1", "type": "line", "sourceLine": 979, "speaker": "动作", "text": "两处干结的泥在同一高度。广告上所谓的窗，在水痕上面不到一只手掌远。"}]}]},
    {"id": "E06-S02.b05", "sourceLine": 981, "type": "line", "speaker": "阿良", "text": "你看见他们了？他们隔玻璃不答我。我敲了几年了，手都快没了。"},
    {"id": "E06-S02.b06", "sourceLine": 983, "type": "line", "speaker": "林雨", "text": "您让开半个身子，我先听外头。那孩子箱子还在拖。"}
  ]},
  "E06-S03": {"id": "E06-S03", "chapter": "E06", "title": "八百块", "next": "E06-S04", "time": "5月22日 夜", "place": "楼梯缓台", "cue": "真实出口被违规挂锁；有站在高处的接应人；无现实开锁教程", "beats": [
    {"id": "E06-S03.b01", "sourceLine": 990, "type": "line", "speaker": "旁白", "text": "转租人怕人拿错货，从外侧把通向后巷的格栅扣上了。实际进水从雨棚底下反涌。阿岑在高处打电话叫人，老许上楼向业主取这扇格栅的备用钥匙。罗叔守在后巷。新租客还攥着押金条。"},
    {"id": "E06-S03.b02", "sourceLine": 992, "type": "line", "speaker": "新租客", "text": "你让我走，那我今晚睡哪里？八百退给我还有地方找。你们都叫我走，没一个给我地址。"},
    {"id": "E06-S03.b03", "sourceLine": 994, "type": "line", "speaker": "林雨", "text": "我能给你个眼下就能去的。十二号201门厅，上面有许叔，先坐到他那儿。租金你自己留着条，我陪你问。"},
    {"id": "E06-S03.b04", "sourceLine": 996, "type": "line", "speaker": "旁白", "text": "隔着玻璃，林雨看见一间已经住熟的屋：墙上有被人修过两回的置物架，床脚压一片折成四层的旧年画，花被面上搭着男人新洗的袜子。水涌过插座的位置，那些东西一件件安静浮起来。阿哲一眼也没看见，却忽然弯腰避开了一只从高处掉下来的真实塑料盆。盆底用圆珠笔写着三个电话号码，末一行已经泡得晕开。"},
    {"id": "E06-S03.b05", "sourceLine": 998, "type": "line", "speaker": "旁白", "text": "阿良在她身后越敲越急。玻璃里的每个人都伸手要求开门，连刚听过的妈妈声音也在里头。林雨转身，差点把手从活人的箱带上松开。"},
    {"id": "E06-S03.b06", "sourceLine": 1000, "type": "interaction", "kind": "choice", "prompt": "先稳住谁？", "options": [{"id": "E06-S03.b06.o1", "label": "请新租客说出箱里带了什么", "sourceLine": 1002, "feedback": [{"id": "E06-S03.b06.o1.f1", "type": "line", "sourceLine": 1004, "speaker": "新租客", "text": "辣椒！两瓶，不要把箱子横着提，一横就漏。"}, {"id": "E06-S03.b06.o1.f2", "type": "line", "sourceLine": 1006, "speaker": "动作", "text": "他开始用自己的声音指挥阿岑怎么接。林雨跟着这句活话踩稳台阶。"}, {"id": "E06-S03.b06.o1.name", "type": "line", "speaker": "新租客", "text": "我叫阿哲。到了上头你喊我一声，我来提。", "origin": "continuity"}]}, {"id": "E06-S03.b06.o2", "label": "请阿岑当面点答得到名字的人", "sourceLine": 1008, "feedback": [{"id": "E06-S03.b06.o2.f1", "type": "line", "sourceLine": 1010, "speaker": "阿岑", "text": "林雨？许叔？穿绿衣那个，你叫什么？"}, {"id": "E06-S03.b06.o2.f2", "type": "line", "sourceLine": 1012, "speaker": "新租客", "text": "我叫阿哲。我还没给你们我妈的电话呢，怎么就开始点名！"}]}]},
    {"id": "E06-S03.b07", "sourceLine": 1014, "type": "line", "speaker": "林雨", "text": "阿良，后门那道闩，以前也在外头吗？"},
    {"id": "E06-S03.b08", "sourceLine": 1016, "type": "line", "speaker": "旁白", "text": "阿良用水桶在栏杆外壁磕出一声。他指了个方向。林雨看见几十只手隔水伸向开不到的一边。她让罗叔从现实的巷口确认。"}
  ]},
  "E06-S04": {"id": "E06-S04", "chapter": "E06", "title": "从里面出去", "next": "E07-S01", "time": "5月22日 当夜", "place": "后巷格栅与201", "cue": "动作由四个人分担；无可搜集奖励置于危险区", "beats": [
    {"id": "E06-S04.b01", "sourceLine": 1023, "type": "line", "speaker": "罗叔", "text": "旧锁环从来在这面。出水那天，最后那一下谁挂的我没见。今天我在场，门是从外边扣的。"},
    {"id": "E06-S04.b02", "sourceLine": 1025, "type": "line", "speaker": "旁白", "text": "阿岑在外头照明，老许把备用钥匙交给罗叔；格栅往外拉开。阿哲把自己的箱子留在高台，自己先出去，然后接住林雨。现实两个人都脱离积水后，回到林雨视点：阿良仍在同一块玻璃前敲。"},
    {"id": "E06-S04.b03", "sourceLine": 1027, "type": "line", "speaker": "林雨", "text": "你把声音叫大些，我去外头听。你想叫哪个，我就替你应一声。"},
    {"id": "E06-S04.b04", "sourceLine": 1029, "type": "line", "speaker": "阿良", "text": "最后一床，花被面。她都搬去佛山几年了。我每次敲到跟前才记得。"},
    {"id": "E06-S04.b05", "sourceLine": 1031, "type": "line", "speaker": "林雨", "text": "那你还敲吗？"},
    {"id": "E06-S04.b06", "sourceLine": 1033, "type": "line", "speaker": "旁白", "text": "阿良把桶放下。水面平了一会儿，第五格终于只剩一床湿被子。没有人替他宣布可以走了。林雨上去，阿岑把干毛巾扔给她，刚好罩住整张脸。"},
    {"id": "E06-S04.b07", "sourceLine": 1035, "type": "line", "speaker": "转租人", "text": "八百，这个价他自己点头的呀。"},
    {"id": "E06-S04.b08", "sourceLine": 1037, "type": "line", "speaker": "阿哲", "text": "我点过头。今天你从外面把我关在里头，我哪回点头了？"},
    {"id": "E06-S04.b09", "sourceLine": 1039, "type": "line", "speaker": "旁白", "text": "阿哲自己留存广告、押金条和当晚录到的通话，向有关人员反映这处仍在招租；罗叔愿提供自己亲见的锁位。老许陪他在201坐到同行来接。几天后转租人退还押金；旧案责任仍须另行查证。"},
    {"id": "E06-S04.b10", "sourceLine": 1041, "type": "interaction", "kind": "choice", "prompt": "本人允许团队保留哪份可回查的实物记录？", "options": [{"id": "E06-S04.b10.o1", "label": "抄下仍在使用的柜台联系方式；阿哲保管广告原件", "sourceLine": 1043, "feedback": [{"id": "E06-S04.b10.o1.f1", "type": "line", "sourceLine": 1045, "speaker": "阿哲", "text": "公开给人看锁环就够了。这号我交材料用，你先留一个能找回我的索引。"}]}, {"id": "E06-S04.b10.o2", "label": "请罗叔画出从哪面看得见锁环", "sourceLine": 1047, "feedback": [{"id": "E06-S04.b10.o2.f1", "type": "line", "sourceLine": 1049, "speaker": "罗叔", "text": "这张标了入口方向，拿去让人看。有人问当年是谁扣锁的，回来找我，我还是那句话。"}]}]},
    {"id": "E06-S04.b11", "sourceLine": 1051, "type": "set", "text": "出口朝向核对", "record": "grille", "scope": "public", "holder": "罗叔", "detail": "只公开本人确认的锁环朝向，不推定当年是谁扣锁。"},
    {"id": "E06-S04.contact", "type": "set", "record": "rental-contact", "text": "广告回查索引", "scope": "private", "holder": "阿哲", "detail": "原广告和押金条由阿哲保管。回查须联系本人，直播不可出示号码。", "when": "E06-S04.b10.o1", "origin": "permission"},
    {"id": "E06-S04.b12", "sourceLine": 1053, "type": "line", "speaker": "旁白", "text": "阿哲在201拿插座给手机充电，拍了两瓶辣椒发给妈妈。照片只拍到一张干桌子。他说等真找到带灶的房再补另一张。老许让他先留一瓶，省得下次搬得沉。到月底，瓶子还在等主人来拿。"},
    {"id": "E06-S04.ownwords.1", "type": "line", "speaker": "旁白", "text": "追押金那天，老许也跟阿哲跑了一趟。晚上看样片，林雨把老许认出隔板的那段放给他看，镜头停在他搬隔板的手上。", "origin": "outline-bridge"},
    {"id": "E06-S04.ownwords.2", "type": "line", "speaker": "老许", "text": "后头我说知道那儿摆了床，你怎么剪没了？加回去。下一个来交钱的，说不定会多问一句，这门从里边开不开得了。", "origin": "outline-bridge"},
    {"id": "E06-S04.ownwords.3", "type": "line", "speaker": "林雨", "text": "我怕熟人认出您。您听一下，我从第二趟开始接。", "origin": "outline-bridge"}
  ]},
  "E07-S01": {"id": "E07-S01", "chapter": "E07", "title": "只歇星期二", "next": "E07-S02", "time": "6月18日 下午", "place": "老生意街", "cue": "公告牌被取件条盖去一半；茶桌旁有两张不同的凳", "beats": [
    {"id": "E07-S01.b01", "sourceLine": 1064, "type": "line", "speaker": "旁白", "text": "陈伯去复诊，决定以后只做半天，铺里半边柜台借给黄姨堆待取的衣袋。罗叔星期二去给女儿带娃。三个老人头一次发现，照各自贴的营业时间，星期二没有一个地方能把东西取齐。"},
    {"id": "E07-S01.b02", "sourceLine": 1066, "type": "line", "speaker": "陈伯", "text": "我女儿叫我关铺，说我一天挣的还不够打车看腿。我前天找一颗鞋跟螺钉，附近五金铺问个遍，只收人几块。她算给我看，连走路那四十分钟也要算工钱。"},
    {"id": "E07-S01.b03", "sourceLine": 1068, "type": "line", "speaker": "阿岑", "text": "她给你算亏的，你非往赚的算。我爸也这样。"},
    {"id": "E07-S01.b04", "sourceLine": 1070, "type": "line", "speaker": "陈伯", "text": "那你去给她提意见。先帮我把左边那双从箱底拿出来，我可不想今儿晚上给人两只右脚。"},
    {"id": "E07-S01.b05", "sourceLine": 1072, "type": "line", "speaker": "旁白", "text": "一份自称“夜访街巷指引”的网帖把三家店标成灵异打卡点，给领取号上不同的地址起了“生门”“死门”。已有观众拿着截屏来问一位女顾客是不是住过鱼缸房。帖中有星环的试投短链。《夜访》没有发过这张图。"},
    {"id": "E07-S01.b06", "sourceLine": 1074, "type": "line", "speaker": "黄姨", "text": "你来问我怎么改袖子，我能讲一天。你拿这张问我，她住哪里，我连她进没进来都不告诉你。"},
    {"id": "E07-S01.b07", "sourceLine": 1076, "type": "line", "speaker": "旁白", "text": "林雨记下旧图的公开链接与发布时间。陈伯要她先办正事，把今天没人来取的三件东西交回各自主人的柜子。"},
    {"id": "E07-S01.tuesday.1", "type": "line", "speaker": "林雨", "text": "周二下午，先算上我一个。", "origin": "outline-bridge"},
    {"id": "E07-S01.tuesday.2", "type": "line", "speaker": "阿岑", "text": "七月以后你还住不住这儿？少接半天活，得从哪笔钱里出？咱俩回去算算，再跟陈伯定。", "origin": "outline-bridge"}
  ]},
  "E07-S02": {"id": "E07-S02", "chapter": "E07", "title": "左脚走过的路", "next": "E07-S03", "time": "6月18日 黄昏", "place": "修鞋档", "cue": "老电视反光延伸街面；硬币声和鞋钉声有别", "beats": [
    {"id": "E07-S02.b01", "sourceLine": 1083, "type": "line", "speaker": "旁白", "text": "一双一大一小的旧帆布鞋等在修鞋档外。林雨提起鞋袋，街突然长了，三个拎工具袋的人各走各的，一停就被后面的人从身体里穿过去。前面的人左脚不着力。阿岑只听得到一轻一重的钉声，示意她看鞋跟。"},
    {"id": "E07-S02.b02", "sourceLine": 1085, "type": "line", "speaker": "陈伯", "text": "看哪里先磨穿。你别叫人跑起来。钉脚的那双，我还欠他一张垫片。"},
    {"id": "E07-S02.b03", "sourceLine": 1087, "type": "interaction", "kind": "inspect", "prompt": "查哪处补痕能找到主人？", "options": [{"id": "E07-S02.b03.o1", "label": "翻看左鞋垫内侧半寸厚的补片", "sourceLine": 1089, "feedback": [{"id": "E07-S02.b03.o1.f1", "type": "line", "sourceLine": 1091, "speaker": "动作", "text": "厚垫恰好避开一处老钉伤。走得最慢的人掉头等她，脱下左鞋试了两步，终于肯坐。"}]}, {"id": "E07-S02.b03.o2", "label": "对柜上重复使用的袋号与旧鞋底的铅笔字", "sourceLine": 1093, "feedback": [{"id": "E07-S02.b03.o2.f1", "type": "line", "sourceLine": 1095, "speaker": "动作", "text": "四十三号袋换过绳，鞋底的三角点还在。陈伯把袋子递给走在最后的客人，给脚跟让出一点余地。"}]}]},
    {"id": "E07-S02.b04", "sourceLine": 1097, "type": "line", "speaker": "陈伯", "text": "你有本事见到他，也得问穿着合不合脚。我这么讲究，哪能叫他跑回来第二趟。"},
    {"id": "E07-S02.b05", "sourceLine": 1099, "type": "line", "speaker": "旁白", "text": "那人坐下时，街短了。真正等取鞋的骑手在柜台边试穿，老板没和他说那些旧事。阿岑替陈伯把茶桌边歪的一只脚重新垫平。"}
  ]},
  "E07-S03": {"id": "E07-S03", "chapter": "E07", "title": "把原来的边留着", "next": "E07-S04", "time": "6月18日 夜", "place": "黄姨改衣铺", "cue": "裁衣镜与现实试衣镜有不同边框；撤回镜面拍摄", "beats": [
    {"id": "E07-S03.b01", "sourceLine": 1106, "type": "line", "speaker": "旁白", "text": "姑娘穿来一条裤脚滚着粗线的牛仔裤，想改短，又舍不得那道边。黄姨先让她坐下再站起来，摸到她膝盖弯的位置，用粉在靠上一截画了两个圈。"},
    {"id": "E07-S03.b02", "sourceLine": 1108, "type": "line", "speaker": "黄姨", "text": "原边留着，从上头收。你腿长得像哪张尺码表，我得看你穿着才知道。"},
    {"id": "E07-S03.b03", "sourceLine": 1110, "type": "line", "speaker": "旁白", "text": "姑娘出帘时，林雨在镜子里看见自己穿着好几件不合身的衣服。每件都让她抬不起手，领口垂着一大沓“懂事”“不挑活”“肯熬夜”的旧领标。她的摄影证压在最底下。"},
    {"id": "E07-S03.b04", "sourceLine": 1112, "type": "line", "speaker": "林雨", "text": "你这里还给人拆牌子？"},
    {"id": "E07-S03.b05", "sourceLine": 1114, "type": "line", "speaker": "黄姨", "text": "拆哪道，你挑。领标扎肉，改松一寸也行。别等人来取衣服，我才晓得剪错人家的布。"},
    {"id": "E07-S03.b06", "sourceLine": 1116, "type": "interaction", "kind": "choice", "prompt": "选择保留衣服的哪一处。", "options": [{"id": "E07-S03.b06.o1", "label": "从内侧拆掉扎颈那针，保留旧布", "sourceLine": 1118, "feedback": [{"id": "E07-S03.b06.o1.f1", "type": "line", "sourceLine": 1120, "speaker": "动作", "text": "整排标签滑出。衣袋里还有母亲寄来的洗衣票，林雨单独留下，抻直领口。"}]}, {"id": "E07-S03.b06.o2", "label": "给自己的衣服补出一个能放公交卡的兜", "sourceLine": 1122, "feedback": [{"id": "E07-S03.b06.o2.f1", "type": "line", "sourceLine": 1124, "speaker": "动作", "text": "镜子里的工牌缩回线缝，新口袋里一张公交卡沉到底。林雨抬手，第一次够到门边。"}]}]},
    {"id": "E07-S03.b07", "sourceLine": 1126, "type": "line", "speaker": "旁白", "text": "姑娘同意林雨用“旧牛仔裤改短”的局部照示范原边手艺。走了三步，她又回来。母亲也穿过这条裤子，会认得她缝上去的补花。她改了主意。林雨当面删除局部照，在节目索引写“取回”，把她签过名字那页还给本人。"},
    {"id": "E07-S03.b08", "sourceLine": 1128, "type": "line", "speaker": "姑娘", "text": "我明天还能来拿裤子吧？"},
    {"id": "E07-S03.b09", "sourceLine": 1130, "type": "line", "speaker": "黄姨", "text": "你押金付在我这儿，又没押给电视台。明天下午，等线到了，早上来我也没有。"},
    {"id": "E07-S03.b10", "sourceLine": 1132, "type": "set", "text": "衣物图像授权已撤回", "record": "garment", "scope": "withdrawn", "holder": "姑娘本人", "detail": "局部照已当面删除，授权页交回本人。节目索引只留取回状态。"}
  ]},
  "E07-S04": {"id": "E07-S04", "chapter": "E07", "title": "无齿的钥匙", "next": "E07-S05", "time": "6月19日 傍晚", "place": "钥匙档", "cue": "三柜三钥；放错可原处重来；无齿坯单独建图", "beats": [
    {"id": "E07-S04.b01", "sourceLine": 1139, "type": "line", "speaker": "旁白", "text": "开门之前，有个人到柜台求配钥匙，说母亲让我来，住了十多年，邻居全认得。罗叔让他照登记本留的电话找本人确认。他掏出手机，里面是网上随手能存的门牌照片。罗叔合住抽屉。那个人转身后，真正来配店门匙的攥着同样的照片到了。罗叔照样等回电。"},
    {"id": "E07-S04.b02", "sourceLine": 1141, "type": "line", "speaker": "林雨", "text": "熟人也等？"},
    {"id": "E07-S04.b03", "sourceLine": 1143, "type": "line", "speaker": "罗叔", "text": "认识我就知道，要等。你叫他替我顾壶水，一会儿就开。"},
    {"id": "E07-S04.b04", "sourceLine": 1145, "type": "line", "speaker": "旁白", "text": "郑家那把钥匙的铜屑还在板缝里，楼后格栅的齿印也在。罗叔把三个匣子排开，像让三个不肯相认的旧门在同一张桌上碰一次头。林雨听得到门后的人各自在找原主；阿岑只听见桌板低低振了一下。"},
    {"id": "E07-S04.b05", "sourceLine": 1147, "type": "line", "speaker": "旁白", "text": "罗叔上柜锁了三份代领物：鞋袋放陈伯柜，衣袋放黄姨柜，钥匙领用页由罗叔自己管。不熟的人拿一张旧门牌截屏，什么也领不走。三人各认自己的旧号，把钥匙交还给各自持有人。"},
    {"id": "E07-S04.b06", "sourceLine": 1149, "type": "interaction", "kind": "retry", "prompt": "三家营业时间错开，网上发哪份指引？", "options": [{"id": "E07-S04.b06.o1", "label": "用付修人住址对照袋号，标谁家门近", "sourceLine": 1151, "feedback": [{"id": "E07-S04.b06.o1.f1", "type": "line", "sourceLine": 1153, "speaker": "黄姨", "text": "我这收的是裤脚长短。住哪儿你拿去做什么？重写，只写来哪家柜台。"}], "retry": true}, {"id": "E07-S04.b06.o2", "label": "按取件号找柜台，写明周二暂存和本人核验", "sourceLine": 1155, "feedback": [{"id": "E07-S04.b06.o2.f1", "type": "line", "sourceLine": 1157, "speaker": "动作", "text": "三家各收一份。粉叔的桌子只贴营业时间，真正的号码放柜台里面。"}]}]},
    {"id": "E07-S04.b07", "sourceLine": 1159, "type": "line", "speaker": "旁白", "text": "罗叔从钥匙盘里拣出一片光滑的坯，说另有一间闲着的旧柜档，按月可用。真有人愿意定时来替街坊查旧记录，就拿这片坯作记号，签了使用约定再配齿。没人照看，柜档就照旧挂锁。"},
    {"id": "E07-S04.b08", "sourceLine": 1161, "type": "interaction", "kind": "choice", "prompt": "谁来保管将来的柜档钥匙坯？", "options": [{"id": "E07-S04.b08.o1", "label": "收下无齿坯，答应先试排一个值班月", "sourceLine": 1163, "feedback": [{"id": "E07-S04.b08.o1.f1", "type": "line", "sourceLine": 1165, "speaker": "林雨", "text": "给我。我先算来回要多少车钱。日子排不出我会当面还你。"}, {"id": "E07-S04.b08.o1.f2", "type": "line", "sourceLine": 1167, "speaker": "罗叔", "text": "没齿，拧坏了别赖我。"}]}, {"id": "E07-S04.b08.o2", "label": "交回罗叔，她只把取件办法写完整", "sourceLine": 1169, "feedback": [{"id": "E07-S04.b08.o2.f1", "type": "line", "sourceLine": 1171, "speaker": "林雨", "text": "现在我还不知道下个月住哪儿。先留在你那块木板上，等能值班的人来拿。"}, {"id": "E07-S04.b08.o2.f2", "type": "line", "sourceLine": 1173, "speaker": "罗叔", "text": "好。你这样讲我倒省事。帮我把挂绳穿回去。"}]}]},
    {"id": "E07-S04.b08.o1.key", "type": "set", "text": "试排值班月的无齿坯", "record": "cabinet-key", "scope": "private", "holder": "林雨", "detail": "本人先保管，待排定值班、签约后配齿。", "when": "E07-S04.b08.o1", "origin": "permission"},
    {"id": "E07-S04.b08.o2.key", "type": "set", "text": "柜档钥匙坯已交回", "record": "cabinet-key", "scope": "returned", "holder": "罗叔", "detail": "钥匙坯留在罗叔的木板上，林雨只整理取件办法。", "when": "E07-S04.b08.o2", "origin": "permission"},
    {"id": "E07-S04.b09", "sourceLine": 1175, "type": "line", "speaker": "旁白", "text": "阿岑请沈嘉查那个短链。沈嘉回传星环发给她本人要求排期的工作邮件，附试投图和设计说明；仅准团队核对，正式追问用公开截图。邮件里的出镜人一栏写着林雨。林雨看了半天，认出那张“生门”的底图，是她最早放上网的一帧雨巷。"},
    {"id": "E07-S04.b10", "sourceLine": 1177, "type": "set", "text": "短链试投的时间与署名", "record": "campaign", "scope": "public", "holder": "夜访／沈嘉", "detail": "公开只用已经发布的截图说明日期和署名；沈嘉收到的邮件仅供私下核对。"}
  ]},
  "E07-S05": {"id": "E07-S05", "chapter": "E07", "title": "谁来点灯", "next": "E08-S01", "time": "6月20日至7月初", "place": "粉摊与剪辑桌", "cue": "三铺照常营业；手机群里的转发音从密到稀", "beats": [
    {"id": "E07-S05.b01", "sourceLine": 1184, "type": "line", "speaker": "旁白", "text": "星环回复，愿意撤掉指引，改谈一期“今宵剧场”直播，交付方式由《夜访》自选；若独家签约，商务部门仍保留切片包装权。周铭的理由说得很直：上次试投已有人愿意买广告，频道也拖欠着下一季的成本。"},
    {"id": "E07-S05.b02", "sourceLine": 1186, "type": "line", "speaker": "阿岑", "text": "你先别替我推这笔钱。我跟了十六场婚宴，回家听冰箱响都以为新郎该入场。能固定做自己的片，我真想要。但咱们辛苦攒的号，最后那一下得咱们自己按。"},
    {"id": "E07-S05.b03", "sourceLine": 1188, "type": "line", "speaker": "林雨", "text": "我也想要。要到我都忘了问，人家拿什么起的名字。"},
    {"id": "E07-S05.b04", "sourceLine": 1190, "type": "line", "speaker": "粉叔", "text": "今宵是这条巷子以前放露天戏的叫法。收音机、电视、铁牌，坏过多少回了，叫法还在。你要开播，在我棚里架一张桌，别把我这锅占去。我还做生意。"},
    {"id": "E07-S05.audience.1", "type": "line", "speaker": "小茵", "text": "我想让原先骂过琴姐的那些人也听一回。镜头朝哪儿，我自己挑。", "origin": "outline-bridge"},
    {"id": "E07-S05.b05", "sourceLine": 1192, "type": "line", "speaker": "旁白", "text": "周铭给了7月18日晚的栏目档期，到点才见得到首页推介。林雨当面和小茵约好，无论签不签合作，借自己账号在那晚把开门声给当初那些观众听全。6月底，林雨把302再续到7月27日。她把授权到哪一秒、谁要求取回、哪些只能核对逐项排上剪辑时间线。那夜302的旧电视没有人像，只映出一张空凳。她把桌上的水杯往里挪了一寸。"}
  ]},
  "E08-S01": {"id": "E08-S01", "chapter": "E08", "title": "场租和晚饭", "next": "E08-S02", "time": "7月18日 17:40", "place": "粉摊临时播出台", "cue": "旧屏只接预监；主频道在团队手机；分轨供字幕", "beats": [
    {"id": "E08-S01.b01", "sourceLine": 1203, "type": "line", "speaker": "旁白", "text": "阿岑把延长线贴在桌腿内侧，给推婴儿车的人留出过道。周铭提着两盒饭准点到，箱子上放一份独家合约，封面写保底月费、器材预支和素材再剪权限。"},
    {"id": "E08-S01.b02", "sourceLine": 1205, "type": "line", "speaker": "周铭", "text": "我知道你们怕我换标题。现在给你两路：我们审好的那条，签约就推首页；你们自己做，号归你，带宽我也不替你买。两种都写这儿。你不干，饭拿去吃。"},
    {"id": "E08-S01.b03", "sourceLine": 1207, "type": "line", "speaker": "林雨", "text": "楼梯那张图，上回你怎么让人写“附近住户推荐”？"},
    {"id": "E08-S01.b04", "sourceLine": 1209, "type": "line", "speaker": "周铭", "text": "执行觉得那样像人话。我看了。那张一出去，问档口的人才多。我当时让他挂到晚上。"},
    {"id": "E08-S01.b05", "sourceLine": 1211, "type": "line", "speaker": "旁白", "text": "阿岑打开当日公众能见的试投留档和节目组给自己的授权单。前者已使用《夜访》署名，后者签字栏还空着。林雨把两份日期对齐，自己复原了误导怎么发生。现场只有这一张桌，两路只占自家频道的一个源，最终发送按钮在林雨手边。"},
    {"id": "E08-S01.b06", "sourceLine": 1213, "when": "E05-S04.b05.o1", "type": "line", "speaker": "手机·沈嘉", "text": "五月你在群里署过名的回复我找到了。那天明确说过哪些镜头不能错接，时间在试投之前。"},
    {"id": "E08-S01.b07", "sourceLine": 1215, "when": "E05-S04.b05.o2", "type": "line", "speaker": "阿岑", "text": "五月那份私聊我备份了。它能说明咱俩同意过什么；对外那段时间，确实看不到我们怎么回的。"}
  ]},
  "E08-S02": {"id": "E08-S02", "chapter": "E08", "title": "见得到的人", "next": "E08-S03", "time": "7月18日 入夜", "place": "三巷与粉摊", "cue": "红伞鬼身仅林雨层；观众只能看物理事件、获许可的活人声", "beats": [
    {"id": "E08-S02.b01", "sourceLine": 1222, "type": "line", "speaker": "旁白", "text": "有人举手机蹲在三号桌前等红伞。阿琴把粉叔家属的电话号码从炉边夹板上遮住，阿岑扶起挡路的折凳。阿哲来拿存在201的辣椒，一瓶还剩大半，另一瓶盖上贴着老许写的“有人回来拿”。"},
    {"id": "E08-S02.b02", "sourceLine": 1224, "type": "line", "speaker": "阿哲", "text": "你们今天不边走边拍吧？我换了工，我妈才知道我以前那房什么样。你们别把手机往我这边转。"},
    {"id": "E08-S02.b03", "sourceLine": 1226, "type": "line", "speaker": "林雨", "text": "今天摄像头朝桌面。罗叔，你说锁的时候我把画拍窄点。"},
    {"id": "E08-S02.b04", "sourceLine": 1228, "type": "line", "speaker": "旁白", "text": "小茵把七秒视频的公开范围又听了一遍。梁安的旧队友在旁边点了四份粉，没给十七号机留拍照点。有人抱怨跑一趟什么都没有。"},
    {"id": "E08-S02.b05", "sourceLine": 1230, "when": "E04-S02.b02.o1", "type": "line", "speaker": "旁白", "text": "粉叔把旧回单压在一本翻烂的电话簿里。那位家属还在比笔迹，桌上留“待核”两个字，直播没人替她下结论。"},
    {"id": "E08-S02.b06", "sourceLine": 1232, "when": "E04-S02.b02.o2", "type": "line", "speaker": "旁白", "text": "带饭缸轮廓的回单夹在账页背面。粉叔给它盖张小纸片，免得镜头把折起来的屋号映到玻璃上。"},
    {"id": "E08-S02.b07", "sourceLine": 1234, "type": "line", "speaker": "旁白", "text": "第一次牌响，林雨看见一起等灯的亡者到了，各自坐好。有人撑伞，有人端空碗，有人进来还先擦鞋。阿岑只觉得身后多了几种重量不同的座椅响。直播还在倒数。屏幕里那一排椅子依旧空着。"},
    {"id": "E08-S02.b08", "sourceLine": 1236, "when": "E03-S05.b05.o1", "type": "line", "speaker": "旁白", "text": "梁安把四枚硬币无声地排在桌子靠他那边。林雨知道过弯的杯子得往反方向挪。"},
    {"id": "E08-S02.b09", "sourceLine": 1238, "when": "E03-S05.b05.o2", "type": "line", "speaker": "声画", "text": "空桌沿响了四下。隔壁摊收款提示也在响，阿岑却抬头朝空椅扬了扬下巴。"},
    {"id": "E08-S02.b10", "sourceLine": 1240, "type": "line", "speaker": "小梅", "text": "他今天吃过了。别拍我爸吃饭。我就是过来看看你最后播什么。"},
    {"id": "E08-S02.b11", "sourceLine": 1242, "type": "line", "speaker": "林雨", "text": "你想坐最边那儿吗？人来来去去要挤。"},
    {"id": "E08-S02.b12", "sourceLine": 1244, "type": "line", "speaker": "小梅", "text": "就边上。走的时候不用人给我让路。"}
  ]},
  "E08-S03": {"id": "E08-S03", "chapter": "E08", "title": "今晚用哪一路", "next": null, "time": "7月18日 20:55", "place": "频道控制桌", "cue": "选项前可回看两份方案与财务约定；锁定条件显示原因", "beats": [
    {"id": "E08-S03.b01", "sourceLine": 1251, "type": "line", "speaker": "旁白", "text": "周铭的审定片只有《夜访》自有的空巷、柜门和红灯，没有未经同意的原件。它将窄门关上的画面放在“女孩求助”之后，掐了开门声；片尾是「你敢来吗」。这样剪，观众很容易重新相信那个早已更正的标题。周铭拿出合同给两位合伙人签。"},
    {"id": "E08-S03.b02", "sourceLine": 1253, "type": "line", "speaker": "阿岑", "text": "先把话说清。我拍那扇门的时候，它开着。独家你真想签，我不拦。署名写掌镜就行，这个剪口我不认。以后出什么事，你得能找到我。"},
    {"id": "E08-S03.b03", "sourceLine": 1255, "type": "line", "speaker": "林雨", "text": "自播的话呢？"},
    {"id": "E08-S03.b04", "sourceLine": 1257, "type": "line", "speaker": "阿岑", "text": "我守着线。你掉词就喝水，我不催。下个月镜头我还是租。"},
    {"id": "E08-S03.b05", "sourceLine": 1259, "type": "interaction", "kind": "branch", "prompt": "玩家决定节目怎样上屏。", "options": [{"id": "E08-S03.b05.o1", "label": "签下星环独家合作，交付审定片", "sourceLine": 1261, "feedback": [{"id": "E08-S03.b05.o1.f1", "type": "line", "sourceLine": 1263, "speaker": "动作", "text": "两人各自签署权利栏。阿岑在附页记下不认同的剪口；林雨以发布人身份按下交付键。"}], "to": "E08-S08"}, {"id": "E08-S03.b05.o2", "label": "用《夜访》自己的号开证人桌，放弃独家保底", "sourceLine": 1265, "feedback": [{"id": "E08-S03.b05.o2.f1", "type": "line", "sourceLine": 1267, "speaker": "动作", "text": "周铭把合同拢回包里，留下两盒饭。林雨将桌面的白纸铺平，把手机交给小茵先核对画面。"}], "to": "E08-S04"}]}
  ]},
  "E08-S04": {"id": "E08-S04", "chapter": "E08", "title": "给愿意开口的人", "next": "E08-S05", "time": "7月18日 21:00", "place": "证人桌", "cue": "证物来源和用途核对；首次公众公开仅使用批准片段", "beats": [
    {"id": "E08-S04.b01", "sourceLine": 1274, "type": "line", "speaker": "小茵", "text": "我不要露脸，那七秒你们记得了吧？开门以后那句，还是我妈的事。"},
    {"id": "E08-S04.b02", "sourceLine": 1276, "type": "line", "speaker": "林雨", "text": "剪到轴响。谁都别给她接一句话。"},
    {"id": "E08-S04.correction.1", "type": "line", "speaker": "小茵", "text": "门是我开的。那一晚我就在对街。", "origin": "outline-bridge"},
    {"id": "E08-S04.b03", "sourceLine": 1278, "type": "interaction", "kind": "choice", "prompt": "在更正之后，完整交代哪一项？", "options": [{"id": "E08-S04.b03.o1", "label": "播开门声和同机位的遮挡", "sourceLine": 1280, "feedback": [{"id": "E08-S04.b03.o1.f1", "type": "line", "sourceLine": 1282, "speaker": "声画", "text": "小茵亲手点播放，屏幕标出原片止处。林雨从镜头前往右移一步，阿琴将门推开。观众看见这一步有多远。"}, {"id": "E08-S04.b03.o1.f2", "type": "line", "sourceLine": 1284, "speaker": "阿琴", "text": "今天是我推的，那天是她推的。水还买不买？不买我关冰柜。"}]}, {"id": "E08-S04.b03.o2", "label": "播老邓的亲历，把采访原带留给朋友", "sourceLine": 1286, "feedback": [{"id": "E08-S04.b03.o2.correction", "type": "line", "speaker": "声画", "text": "先放开门那一声。音轨到门轴响就停住，小茵收起手机，把桌面让给下一位。", "origin": "outline-bridge"}, {"id": "E08-S04.b03.o2.f1", "type": "line", "sourceLine": 1288, "speaker": "老邓", "text": "电脑开了四十二分钟。人等到两点。头一个数字我有账，后面这个是我关门时看表的。给孩子打过多久游戏算账，别把那两样加一块。"}, {"id": "E08-S04.b03.o2.f2", "type": "line", "sourceLine": 1290, "speaker": "动作", "text": "旧采访未上传。朋友留存的语音里响起一声杯子打翻，这次过弯自己去拿抹布。"}]}, {"id": "E08-S04.b03.o3", "label": "请罗叔在桌上比旧格栅内外", "sourceLine": 1292, "feedback": [{"id": "E08-S04.b03.o3.correction", "type": "line", "speaker": "声画", "text": "先放开门那一声。音轨到门轴响就停住，小茵收起手机，把桌面让给下一位。", "origin": "outline-bridge"}, {"id": "E08-S04.b03.o3.f1", "type": "line", "sourceLine": 1294, "speaker": "罗叔", "text": "我只能指出哪头在里面。那年我到时锁已经挂着。挂的人我没看见。今天这个朝向你可以画下来。"}, {"id": "E08-S04.b03.o3.f2", "type": "line", "sourceLine": 1296, "speaker": "动作", "text": "公开画面只有手和纸上的格栅。阿哲的姓名、住处和私下联系号留在本人手机里。"}]}]},
    {"id": "E08-S04.b04", "sourceLine": 1298, "type": "line", "speaker": "旁白", "text": "林雨补上试投截图的日期，说明当时自己尚未签字，并承认巷口底图出自她账号。镜头转向桌上空格——那是姑娘取回改衣单留下的位置。阿岑没把镜头推近。桌后传来一声很轻的“谢了”，他分不清是哪个人。"},
    {"id": "E08-S04.b05", "sourceLine": 1300, "when": "E06-S04.b10.o1", "type": "line", "speaker": "阿哲", "text": "我收着原广告。有人想对那家问价的日期，你把他话带给我，我自己回。"},
    {"id": "E08-S04.b06", "sourceLine": 1302, "when": "E06-S04.b10.o2", "type": "line", "speaker": "罗叔", "text": "先看标方向那张图。你照着画一遍，就知道站在屋里哪边够不着。"},
    {"id": "E08-S04.b07", "sourceLine": 1304, "when": "E07-S04.b08.o1", "type": "line", "speaker": "动作", "text": "裤袋里的无齿坯贴着林雨的腿，冷了一个晚上，现在终于有点温度。"},
    {"id": "E08-S04.b08", "sourceLine": 1306, "type": "line", "speaker": "旁白", "text": "第二声牌响，旧荧屏在各自的屋里亮了一瞬。阿岑的预监仍是棚下那张桌。林雨抬眼，看见梁安挤进一群大人中间，踮脚看弹幕。"},
    {"id": "E08-S04.b09", "sourceLine": 1308, "type": "line", "speaker": "梁安", "text": "他们谁知道我叫什么？"},
    {"id": "E08-S04.b10", "sourceLine": 1310, "type": "line", "speaker": "林雨", "text": "你愿意告诉他们吗？"},
    {"id": "E08-S04.b11", "sourceLine": 1312, "type": "line", "speaker": "梁安", "text": "不了。我队里的人知道就行。"}
  ]},
  "E08-S05": {"id": "E08-S05", "chapter": "E08", "title": "播完以后", "next": null, "time": "7月27日 白天", "place": "三巷十二号", "cue": "自然租约到期；街铺按原营业表开门", "beats": [
    {"id": "E08-S05.b01", "sourceLine": 1319, "type": "line", "speaker": "旁白", "text": "第三声来得很迟。节目已经关了，林雨站在水沟前，听到阿婆那把伞轻轻碰了一下牌。阿琴在屋里喊“里面还有灯”。这句无人补录。粉叔开始给过了饭点的人蒸第二轮。"},
    {"id": "E08-S05.b02", "sourceLine": 1321, "type": "line", "speaker": "旁白", "text": "九天后，老许上楼问302还续不续。罗叔空柜档可以按月借用，需要有人每周二下午到场管理。阿岑把预算写在外拍盒饭的白面：如留下，只留柜档和白日时段，林雨搬去更便宜的后排小间；如离开，能接外地的片，仍能从远处给来访者回电话。"},
    {"id": "E08-S05.b03", "sourceLine": 1323, "when": "E05-S04.b05.o1", "type": "line", "speaker": "旁白", "text": "林雨翻出署名拒剪的回复。负责转交材料的街坊据此确认她愿意在记录上为自己的处理署名。"},
    {"id": "E08-S05.b04", "sourceLine": 1325, "when": "E07-S04.b08.o1", "type": "line", "speaker": "旁白", "text": "罗叔等她把钥匙坯搁下，没替她决定配不配齿。"},
    {"id": "E08-S05.b05", "sourceLine": 1327, "type": "interaction", "kind": "branch", "prompt": "选择这个夏天以后怎样过日子。", "options": [{"id": "E08-S05.b05.o1", "label": "还302钥匙，与街坊逐家交回查阅副本", "sourceLine": 1329, "feedback": [{"id": "E08-S05.b05.o1.f1", "type": "line", "sourceLine": 1331, "speaker": "动作", "text": "林雨折好转交清单，收起一个用了四个月的水杯。"}], "to": "E08-S06"}, {"id": "E08-S05.b05.o2", "label": "认领每周二的旧柜档，开一盏查阅灯", "sourceLine": 1333, "feedback": [{"id": "E08-S05.b05.o2.f1", "type": "line", "sourceLine": 1335, "speaker": "动作", "text": "林雨在值班纸上签下四个周二。罗叔去取一把真正能开柜的钥匙。"}], "to": "E08-S07", "requires": ["E05-S04.b05.o1", "E07-S04.b08.o1"], "lockReason": "须已署名拒剪并收下无齿坯"}]}
  ]},
  "E08-S06": {"id": "E08-S06", "chapter": "E08", "title": "结局一　离开", "next": null, "time": "8月 初", "place": "棠西公交站", "cue": "车内外两层声场", "beats": [
    {"id": "E08-S06.handover.1", "type": "line", "speaker": "旁白", "text": "去车站前，林雨把查阅副本按户交回，到了陈伯铺前专门停了一下。", "origin": "outline-bridge"},
    {"id": "E08-S06.handover.2", "type": "line", "speaker": "林雨", "text": "我接了外地的活。周二我守不了，您得另找人。", "origin": "outline-bridge"},
    {"id": "E08-S06.handover.3", "type": "line", "speaker": "旁白", "text": "阿琴收了最后一瓶水的钱。小茵拎过她一只袋子，两个人慢慢走过水沟，谁也没催谁。", "origin": "outline-bridge"},
    {"id": "E08-S06.return.lease", "type": "set", "text": "302钥匙已还", "record": "lease", "scope": "returned", "holder": "老许", "detail": "由原持有人保管，团队只留交还记录。", "origin": "permission"},
    {"id": "E08-S06.return.zheng", "type": "set", "text": "郑家查阅副本已交回", "record": "zheng", "scope": "returned", "holder": "郑家", "detail": "由原持有人保管，团队只留交还记录。", "origin": "permission"},
    {"id": "E08-S06.return.orders", "type": "set", "text": "回单查阅副本已交回", "record": "orders", "scope": "returned", "holder": "粉叔", "detail": "由原持有人保管，团队只留交还记录。", "origin": "permission"},
    {"id": "E08-S06.return.blank", "type": "set", "text": "柜档钥匙坯已交回", "record": "cabinet-key", "scope": "returned", "holder": "罗叔", "detail": "每周二的试排结束，未配齿的钥匙坯交回柜档。", "when": "E07-S04.b08.o1", "origin": "permission"},
    {"id": "E08-S06.b01", "sourceLine": 1342, "type": "line", "speaker": "旁白", "text": "老许把押金退清，水电抄到昨天。小茵过来还充电宝的短线，上一次落在她公司，这次终于想起来。阿琴把包好的肠粉递到车窗下。"},
    {"id": "E08-S06.b02", "sourceLine": 1344, "type": "line", "speaker": "阿琴", "text": "不收你钱，留账上下次收。你要不回来了，我追到你网上要。"},
    {"id": "E08-S06.b03", "sourceLine": 1346, "type": "line", "speaker": "林雨", "text": "琴姐，你们一辈子靠欠这碟粉记得我啊？"},
    {"id": "E08-S06.b04", "sourceLine": 1348, "type": "line", "speaker": "阿琴", "text": "你让开车的等你两句闲话呀？上去。"},
    {"id": "E08-S06.b05", "sourceLine": 1350, "type": "line", "speaker": "旁白", "text": "有人敲三下车窗。阿岑回头时只见雨棚边甩来一把湿伞，林雨却看见张婆婆转身，在路口给下一班夜车留位。几星期后她在外地收到一通电话，有人找旧票上的店。她按约先问店主，再回拨，没有替人家接下下一个采访。"},
    {"id": "E08-S06.b06", "sourceLine": 1352, "type": "line", "speaker": "片尾", "text": "离开。最后一格，手机通讯录里，“粉叔”下面又加了一行“右耳听不大清”。"},
    {"id": "E08-S06.b07", "sourceLine": 1354, "type": "end", "text": "—— 全剧终 ——"}
  ]},
  "E08-S07": {"id": "E08-S07", "chapter": "E08", "title": "结局二　留下灯", "next": null, "time": "8月 第一个周二", "place": "三巷旧柜档", "cue": "开齿声转拉开小台灯；窗外摊位照常换班", "beats": [
    {"id": "E08-S07.fewer.1", "type": "line", "speaker": "旁白", "text": "自播那晚来看的人比首页少。林雨把旧帖转发的名单一条条翻出来，把小茵同意的更正送回当初看过的人手里。她换租了后排的小间，每周二下午过来替三家看铺。", "origin": "outline-bridge"},
    {"id": "E08-S07.b01", "sourceLine": 1361, "type": "line", "speaker": "旁白", "text": "罗叔在无齿的铜片上配出第一把柜钥匙。柜子里只收本人许可查阅的副本。旧物和原单仍在街坊自己手里，该撤的那页仍空着。"},
    {"id": "E08-S07.cut-key", "type": "set", "text": "旧柜档配好的钥匙", "record": "cabinet-key", "scope": "private", "holder": "林雨", "detail": "每周二本人到场值班，只接收获准查阅的副本。", "origin": "permission"},
    {"id": "E08-S07.b02", "sourceLine": 1363, "type": "line", "speaker": "旁白", "text": "第一个周二没人来。林雨把两盒饭吃掉一盒半，阿岑为半盒饭从另一条街绕回来，站在柜前宣布给她拍一张很有事业前途的遗照。相机举起来，画面里只有她闭着眼打哈欠。他最后没舍得删。"},
    {"id": "E08-S07.b03", "sourceLine": 1365, "type": "line", "speaker": "旁白", "text": "第二个周二，一个女骑手把头盔抱在膝上，想抄一张旧送达单。她坐了半天才说，写“到了”的那个地点离她哥真正等人的地方还差三百米。"},
    {"id": "E08-S07.b04", "sourceLine": 1367, "type": "line", "speaker": "林雨", "text": "你自己画。笔没油了就摁两下，有时候它装死。"},
    {"id": "E08-S07.b05", "sourceLine": 1369, "type": "line", "speaker": "女骑手", "text": "我想先打个电话。"},
    {"id": "E08-S07.b06", "sourceLine": 1371, "type": "line", "speaker": "旁白", "text": "林雨把位置让出来，去隔壁看粉叔把炉火收小。窗外店家有人休息，有人开门，没有谁替全村守夜。她回去时，那盏灯还给一个正在写字的人亮着。"},
    {"id": "E08-S07.b07", "sourceLine": 1373, "type": "line", "speaker": "片尾", "text": "留下灯。桌底下多了一张新的取件牌，写着“周二，来之前可以先问”。"},
    {"id": "E08-S07.b08", "sourceLine": 1375, "type": "end", "text": "—— 全剧终 ——"}
  ]},
  "E08-S08": {"id": "E08-S08", "chapter": "E08", "title": "结局三　签约", "next": null, "time": "8月 初", "place": "新住处与主巷", "cue": "合同打款短信；电视回放只有林雨可见", "beats": [
    {"id": "E08-S08.onair.1", "type": "line", "speaker": "旁白", "text": "签字当晚，首页预告一过，小茵把机位压低到只照桌面。她当着那些观众说，是她穿过雨棚开的门。她亲手放出门轴声，在母亲开口前停住。", "origin": "outline-bridge"},
    {"id": "E08-S08.onair.2", "type": "line", "speaker": "旁白", "text": "第二天，有人到便利店把三月留在评论里的话收了回去，跟阿琴说了声对不住。预告仍能单独转发，没进直播的人只看见那扇门落下来。", "origin": "outline-bridge"},
    {"id": "E08-S08.b01", "sourceLine": 1382, "type": "line", "speaker": "旁白", "text": "第一笔保底到账，团队付清器材租金。阿岑终于买下那支用惯的镜头，拿来拍的第一件事是给朋友婚礼补一组家人合照。林雨搬到有独立灶台的小房间，试着蒸了第一碟肠粉。她把粉浆倒厚了，一折就断。"},
    {"id": "E08-S08.b02", "sourceLine": 1384, "type": "line", "speaker": "旁白", "text": "手机上那条审定片还在涨。有人从空巷画面认出阿琴的店，拿手机等关闸。阿琴叫儿子帮忙挡了两回，后来把侧门的灯朝里挪了一尺。小茵的私信什么都没骂，只发了一个老问题：那七秒以后呢？"},
    {"id": "E08-S08.b03", "sourceLine": 1386, "type": "line", "speaker": "旁白", "text": "林雨坐地上打开更正框。新片的切片权已经交出去，她可以发自己的说明，撤不掉别人早已截走的那声尖叫。她给阿琴打电话，响完没人接。"},
    {"id": "E08-S08.b04", "sourceLine": 1388, "type": "line", "speaker": "旁白", "text": "微波炉叮了一下。新屋没有电视，炉门的黑玻璃里却坐着一个正在剪片的人。画面一遍遍倒回林雨自己切掉开门声的那一格。认出自己靠的是她那一下习惯动作：每次剪走一句话，左手都会先摸一下耳垂。玻璃里的人已经把耳垂揉红了。"},
    {"id": "E08-S08.b05", "sourceLine": 1390, "type": "line", "speaker": "阿岑的语音", "text": "下周那条你自己定。要我来抬机子喊我一声。要我说门没开，那句不要写我。"},
    {"id": "E08-S08.b06", "sourceLine": 1392, "type": "line", "speaker": "旁白", "text": "她把已经凉掉的粉吃了。楼下今晚还有人等阿琴关门。玻璃里，剪片的人终于抬起头，叫了她一声全名。"},
    {"id": "E08-S08.b07", "sourceLine": 1394, "type": "line", "speaker": "片尾", "text": "签约。《今宵剧场》下一位，林雨。"},
    {"id": "E08-S08.b08", "sourceLine": 1396, "type": "end", "text": "—— 全剧终 ——"}
  ]}
}};
